		"seller", seller,
		"buyer", buyer,
		"price", itoa(price),
		"fee", itoa(fee),
		"royalty", itoa(royalty),
		"royaltyRecipient", royaltyRecipient,
		"sellerAmount", itoa(sellerAmount),
		"denom", denom,
		"schemaVersion", SchemaVersion,
	}
}

