// Package memba_market_core holds the frozen, cross-engine money math and event
// schema for the Memba NFT marketplace engines. It is a PURE package (no chain/
// realm imports): split math returns values, event helpers return ordered arg
// slices, and the importing engine performs chain.Emit / banker / MarketTransfer.
//
// Constants are copied verbatim from memba_nft_market_v3 (the deployed reference).
// SplitProceeds must stay behaviorally identical to v3's splitProceeds so every
// engine pays out identically (fee/royalty conformance).
package memba_market_core_v2

import "strconv"

const (
	FeeBPS        = int64(200)                   // 2.0% default platform fee (matches v3)
	MaxFeeBPS     = int64(500)                   // 5% hard ceiling on any per-lane fee (DAO cannot exceed)
	MaxRoyaltyBPS = int64(1000)                  // 10% royalty clamp (defense-in-depth)
	MinPrice      = int64(1000)                  // 0.001 GNOT — prevents fee truncation to zero at FeeBPS
	MaxPrice      = int64(1_000_000_000_000_000) // 1 billion GNOT

	// SettlementDenom is carried on every settlement event for forward-compat with
	// the GRC20 settlement desk (PHASE 3+). Engines settle in ugnot today.
	SettlementDenom = "ugnot"

	// SchemaVersion stamps every event so the indexer can branch parsing
	// deterministically and the schema can evolve without ambiguity. Bump ONLY
	// when an event's key set changes; never reuse a version for a different shape.
	SchemaVersion = "1"
)

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

package memba_market_core_v2

// SplitProceedsBPS computes the three-way split of a sale price into platform fee,
// creator royalty, and seller proceeds, with the platform fee in basis points
// supplied by the caller (read per-lane from memba_market_config) instead of the
// frozen FeeBPS constant. This is the spine that lets every engine charge a
// DAO-tunable, per-lane fee while sharing one audited money-math implementation.
//
// `feeBPS` is validated to [0, MaxFeeBPS] — the 5% ceiling the DAO can never exceed
// — so a misconfigured or compromised config realm cannot make an engine overcharge.
// `royaltyAmount` is the actual amount from RoyaltyInfo (NOT bps); floored at 0 and
// clamped to MaxRoyaltyBPS of price. A zero fee is permitted (feeBPS may legitimately
// be 0, or round to 0 on a small price); engines that must guarantee non-zero protocol
// revenue (e.g. fungible OTC partial fills) enforce a per-fill minimum notional at
// their call site — that is an engine concern, not pure money-math.
func SplitProceedsBPS(price, feeBPS, royaltyAmount int64) (fee, royalty, seller int64) {
	if price < MinPrice {
		panic("price below minimum")
	}
	if price > MaxPrice {
		panic("price above maximum")
	}
	if feeBPS < 0 {
		panic("feeBPS negative")
	}
	if feeBPS > MaxFeeBPS {
		panic("feeBPS above maximum")
	}
	fee = price * feeBPS / 10000
	royalty = royaltyAmount
	if royalty < 0 {
		royalty = 0
	}
	maxRoy := price * MaxRoyaltyBPS / 10000
	if royalty > maxRoy {
		royalty = maxRoy
	}
	if fee+royalty >= price {
		panic("fee plus royalty exceeds price")
	}
	seller = price - fee - royalty
	if seller <= 0 {
		panic("seller amount not positive")
	}
	return
}

// SplitProceeds is the frozen FeeBPS (2.0%) conformance path, kept behaviorally
// identical to memba_nft_market_v3's splitProceeds. It delegates to SplitProceedsBPS
// with the default FeeBPS so existing engines are unchanged.
func SplitProceeds(price, royaltyAmount int64) (fee, royalty, seller int64) {
	return SplitProceedsBPS(price, FeeBPS, royaltyAmount)
}

// Admin operations — DAO-gated, with a 2-step admin handoff and a hard fee ceiling.
// There is intentionally NO Pause() here (see config.gno SAFETY note): pausing the
// fee spine would brick every engine at once. Per-engine Pause() is the kill switch.
package memba_market_config

import (
	"strconv"

	"chain"
)

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func assertAdmin() {
	if caller() != admin {
		panic("admin only")
	}
}

// SetFeeBPS sets a lane's protocol fee in basis points, clamped to [0, MaxFeeBPS].
// A value above the 5% ceiling is rejected so a misconfiguration can never overcharge.
func SetFeeBPS(cur realm, lane string, bps int64) {
	assertAdmin()
	if lane == "" {
		panic("empty lane")
	}
	if bps < 0 || bps > MaxFeeBPS {
		panic("feeBPS out of range")
	}
	feeByLane.Set(lane, bps)
	chain.Emit("FeeBPSChanged", "lane", lane, "bps", itoa(bps))
}

// SetTreasury repoints where every lane's protocol fee flows.
func SetTreasury(cur realm, addr address) {
	assertAdmin()
	if addr == "" {
		panic("empty treasury")
	}
	treasury = addr
	chain.Emit("TreasuryChanged", "treasury", addr.String())
}

// TransferAdmin proposes a new admin (the memba_dao executor). The 2-step handoff
// requires the new admin to AcceptAdmin, so a transfer to a wrong or uncontrolled
// address cannot lock the realm.
func TransferAdmin(cur realm, newAdmin address) {
	assertAdmin()
	if newAdmin == "" {
		panic("empty admin")
	}
	pendingAdmin = newAdmin
	chain.Emit("AdminTransferProposed", "pending", newAdmin.String())
}

// AcceptAdmin completes the handoff. Only the pending admin can call it.
func AcceptAdmin(cur realm) {
	if caller() != pendingAdmin {
		panic("not pending admin")
	}
	admin = pendingAdmin
	pendingAdmin = ""
	chain.Emit("AdminAccepted", "admin", admin.String())
}

// Package memba_market_config is the DAO-owned fee spine for the Memba marketplace.
// It is the single source of truth for the per-lane protocol fee (basis points) and
// the treasury that receives it. Every trade engine (NFT, services, token-OTC, agents)
// reads GetFeeBPS(lane) + GetTreasury() at settlement, so the DAO sets the rate ONCE
// and it applies everywhere — that shared read is what makes the lanes one marketplace.
//
// SAFETY (panel finding C1): the read getters are PURE and NON-FAILING — they never
// panic, and there is intentionally NO Pause(). A per-trade cross-realm read that
// could fail or halt would be a single point of failure able to brick every engine at
// once; instead an engine always gets a usable, bounded value here and clamps locally,
// while each engine keeps its OWN Pause() as the real kill switch. The fee is bounded
// to [0, MaxFeeBPS] on write, so a reader can trust the bound without re-checking.
package memba_market_config

import (
	"chain/runtime/unsafe"

	"gno.land/p/samcrew/avl"
)

// AdminAddress is the samcrew-core 2-of-2 multisig (samcrew-core-test1) — the DAO
// treasury + admin until the memba_dao executor handoff (via TransferAdmin/AcceptAdmin).
// CONFIRMED 2026-06-27. Note: this is INTENTIONALLY the real 2-of-2 multisig, which
// differs from the single-key `g1x7k4628…` hardcoded as admin in the legacy realms
// (memba_collections/v3.1/escrow_v2) — that single-key admin is a pre-existing
// governance gap; the fee spine is owned by the actual multisig from day one.
const AdminAddress = "g10kw7e55e9wc8j8v6904ck29dqwr9fm9u280juh"

const (
	// MaxFeeBPS is the 5% hard ceiling. SetFeeBPS rejects anything above it, so a
	// fat-finger or a compromised proposal can never make a lane overcharge.
	MaxFeeBPS = int64(500)
	// DefaultFeeBPS is returned for an unset/unknown lane so engines always get a
	// usable value (2.0%).
	DefaultFeeBPS = int64(200)
)

var (
	admin        address
	pendingAdmin address
	treasury     address
	feeByLane    = avl.NewTree() // lane string -> int64 bps
)

func init() {
	admin = address(AdminAddress)
	treasury = address(AdminAddress) // treasury = the multisig now (plan decision #1)
	// Seed the launch lanes. "agent" is intentionally unset (TBD) and resolves to
	// DefaultFeeBPS until the DAO sets it when that lane is built.
	feeByLane.Set("nft", int64(200))     // 2.0%
	feeByLane.Set("service", int64(200)) // 2.0% release fee (the 5% cancel fee is escrow-internal → freelancer)
	feeByLane.Set("token", int64(50))    // 0.5% OTC — competitive vs DEX ~0.3%
}

func caller() address { return unsafe.PreviousRealm().Address() }

// ── Read getters — PURE, NON-FAILING (never panic, no Pause) ──────────────────

// GetFeeBPS returns the protocol fee in basis points for a lane. An unset or unknown
// lane returns DefaultFeeBPS. The result is always within [0, MaxFeeBPS] (enforced on
// write). Never panics — an engine must always be able to settle.
func GetFeeBPS(lane string) int {
	v, ok := feeByLane.Get(lane)
	if !ok {
		return int(DefaultFeeBPS)
	}
	return int(v.(int64))
}

// GetTreasury returns the address that receives the protocol fee on every lane.
func GetTreasury() address { return treasury }

// GetLaneConfig returns (feeBPS, treasury) in one read for an engine's settlement path.
func GetLaneConfig(lane string) (int, address) {
	return GetFeeBPS(lane), treasury
}

// GetAdmin returns the current admin (the multisig, or the memba_dao executor after
// the 2-step handoff).
func GetAdmin() address { return admin }

// Render — public read-only view + audit surface for the fee config.
package memba_market_config

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	var sb strings.Builder
	sb.WriteString("# Memba Marketplace — Fee Config\n\n")
	sb.WriteString("DAO-owned per-lane protocol fee + treasury. Engines read this at settlement.\n\n")
	sb.WriteString(ufmt.Sprintf("**Admin:** %s\n", admin.String()))
	if pendingAdmin != "" {
		sb.WriteString(ufmt.Sprintf("**Pending admin:** %s\n", pendingAdmin.String()))
	}
	sb.WriteString(ufmt.Sprintf("**Treasury:** %s\n", treasury.String()))
	sb.WriteString(ufmt.Sprintf("**Fee ceiling:** %d bps (5%%)\n\n", MaxFeeBPS))

	sb.WriteString("| Lane | Fee (bps) |\n|------|-----------|\n")
	feeByLane.Iterate("", "", func(key string, val interface{}) bool {
		sb.WriteString(ufmt.Sprintf("| %s | %d |\n", key, val.(int64)))
		return false
	})
	sb.WriteString(ufmt.Sprintf("\n*Unset lanes default to %d bps.*\n", DefaultFeeBPS))
	return sb.String()
}

package memba_nft_market_v3_1

// Admin operations — multisig-gated controls.
//
// assertAdmin() is the single authorization gate; caller = unsafe.PreviousRealm().Address().
// AdminDelist is pause-exempt (moderation can always remove content).
// SetFeeRecipient changes where platform fees flow (default = AdminAddress).

import (
	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/samcrew/grc721"
)

func assertAdmin() {
	if unsafe.PreviousRealm().Address() != address(AdminAddress) {
		panic("admin only")
	}
}

// Pause halts new trade operations (ListNFT, BuyNFT, MakeOffer, AcceptOffer).
// Value-exit paths (DelistNFT, CancelOffer, ClaimExpiredOffer) remain available.
func Pause(cur realm) {
	assertAdmin()
	paused = true
	chain.Emit("MarketPaused", "by", unsafe.PreviousRealm().Address().String())
}

// Unpause resumes normal operations.
func Unpause(cur realm) {
	assertAdmin()
	paused = false
	chain.Emit("MarketUnpaused", "by", unsafe.PreviousRealm().Address().String())
}

// AdminDelist force-removes any listing. Pause-exempt (moderation).
func AdminDelist(cur realm, collectionID string, tid grc721.TokenID) {
	assertAdmin()
	key := listingKey(collectionID, string(tid))
	if _, exists := listings.Get(key); !exists {
		panic("not listed: " + key)
	}
	listings.Remove(key)
	removeFromOrder(key)
	chain.Emit("AdminDelisted",
		"collection", collectionID,
		"tokenId", string(tid),
		"admin", unsafe.PreviousRealm().Address().String(),
	)
}

// SetFeeRecipient updates the address that receives platform fees.
func SetFeeRecipient(cur realm, addr address) {
	assertAdmin()
	feeRecipient = addr
	chain.Emit("FeeRecipientChanged", "newRecipient", addr.String())
}

package memba_nft_market_v3_1

// v3.1 — structured read getters.
//
// These let the frontend read listings and offers STRUCTURALLY (full addresses,
// deterministic format) instead of scraping the markdown Render(""), which truncated
// addresses and capped at 50 rows. Output is one record per line, pipe-delimited, so
// the client parses by split — no markdown regex, no truncation.

import (
	"strings"

	"chain/runtime/unsafe"
)

// MaxPageSize bounds a single page so a getter can never iterate unboundedly (a
// gas/DoS surface). The frontend pages with offset/limit.
const MaxPageSize = 100

// MarketAddress returns this engine realm's own address — the operator a seller
// approves on the collection (SetApprovalForAll) and the address the collection
// registers via RegisterMarket. Exposed so the frontend and the deploy ceremony can
// read the deterministic address directly instead of hardcoding it.
func MarketAddress() string { return unsafe.CurrentRealm().Address().String() }

// ListingsCount returns the number of active listings (for pagination).
func ListingsCount() int { return len(listingOrder) }

// GetListingsPage returns a page of active listings, one per line:
//
//	collectionID|tokenID|seller|price|createdBlk
//
// Addresses are FULL (never truncated). offset/limit window the insertion-ordered
// listing set; limit is clamped to [1, MaxPageSize].
func GetListingsPage(offset, limit int) string {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > MaxPageSize {
		limit = MaxPageSize
	}
	n := len(listingOrder)
	end := offset + limit
	if end > n {
		end = n
	}

	var sb strings.Builder
	for i := offset; i < end; i++ {
		v, ok := listings.Get(listingOrder[i])
		if !ok {
			continue
		}
		l := v.(*Listing)
		sb.WriteString(l.CollectionID)
		sb.WriteString("|")
		sb.WriteString(l.TokenID)
		sb.WriteString("|")
		sb.WriteString(l.Seller.String())
		sb.WriteString("|")
		sb.WriteString(itoa(l.Price))
		sb.WriteString("|")
		sb.WriteString(itoa(l.CreatedBlk))
		sb.WriteString("\n")
	}
	return sb.String()
}

// GetOffersForToken returns the active offers on one (collection, token), one per line:
//
//	buyer|amount|createdBlk
//
// It uses a PREFIX-RANGE scan over the offer tree — offerKey is "collection:token:buyer",
// so the range ["collection:token:", "collection:token;") reads only this token's
// offers, never a full-tree scan. This is the read that finally lets the frontend wire
// accept-offer and show a token's offers (no offers getter existed before v3.1).
func GetOffersForToken(collectionID, tokenID string) string {
	start := collectionID + ":" + tokenID + ":"
	end := collectionID + ":" + tokenID + ";" // ';' (0x3b) is the byte after ':' (0x3a)

	var sb strings.Builder
	offers.Iterate(start, end, func(_ string, v interface{}) bool {
		o := v.(*Offer)
		sb.WriteString(o.Buyer.String())
		sb.WriteString("|")
		sb.WriteString(itoa(o.Amount))
		sb.WriteString("|")
		sb.WriteString(itoa(o.CreatedBlk))
		sb.WriteString("\n")
		return false
	})
	return sb.String()
}

package memba_nft_market_v3_1

// NFT Marketplace v3 — General-purpose NFT trading for the Memba ecosystem on test13.
//
// v3 is a fork of the audited memba_nft_market_v2 engine, repointed at the new
// canonical registry realm `memba_collections` (was `memba_nft_v2`). It keeps the
// proven structure: CEI payment ordering, IsUserCall guards on payable entrypoints,
// escrowed offers, GRC2981-style royalty settlement, and a platform-fee split.
//
// Changes vs v2:
//   1. Platform fee 2.5% → 2.0% (FeeBPS 250 → 200). See params.gno.
//   2. Every settlement event now carries the payment `denom` (forward-compat for
//      the GRC20 settlement desk; "ugnot" today). See SettlementDenom.
//   3. Settlement is reported via ONE canonical `Sale` event per sale, with a
//      `via` field = "buy" | "offer". v2 emitted BOTH `OfferAccepted` AND
//      `TokenSold` on an accepted offer, which double-counted volume in indexers.
//      v3 collapses that to the single `Sale` event (BuyNFT emits via="buy",
//      AcceptOffer emits via="offer"). The legacy `PurchaseConfirmed` /
//      `OfferAccepted` / `TokenSold` event names are intentionally retired.
//   4. Imports `memba_collections` for MarketTransfer / RoyaltyInfo. The collection
//      ABI is identical to v2's (same signatures), so no call-site adaptation was
//      needed beyond the import path.
//
// SCOPE (this engine): fixed-price listings (list/delist), buy, escrowed offers
// (make/cancel/accept/claim-expired), royalty settlement, platform-fee split,
// IsUserCall guards, pause.
//
// PHASE 3+ (deferred): the following are intentionally NOT built in this engine and
// are follow-on initiatives:
//   - Collection offers (offers on any token in a collection, not a specific id)
//   - Sweep (buy N cheapest listings in one tx)
//   - Auctions (timed / English / Dutch)
//   - GRC20 settlement desk (settle in $MEMBA or other GRC20; SettlementDenom is the
//     forward-compat hook already threaded onto every settlement event)
//   - DAO-curated badge (verified-collection curation)
//   - Points → $MEMBA claim (trading-rewards accrual + claim)
//
// Security:
//   - CEI (Checks-Effects-Interactions) in all payment flows
//   - IsUserCall guard on BuyNFT and MakeOffer (payment-bearing fns)
//   - Offer escrow with OfferTimeoutBlk safety valve (ClaimExpiredOffer)
//   - MinOfferLifetimeBlk prevents instant-cancel front-run
//   - Only original lister can delist (pause-exempt exit)
//   - Self-buy prevention
//   - Defense-in-depth royalty clamp even when collection enforces its own cap

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/samcrew/grc721"
	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"

	core "gno.land/p/samcrew/memba_market_core_v2"   // v3.1: shared per-lane fee math (SplitProceedsBPS)
	cfg "gno.land/r/samcrew/memba_market_config"   // v3.1: DAO-owned per-lane fee + treasury spine
	nft "gno.land/r/samcrew/memba_collections"     // v3 change #4: canonical registry (was memba_nft_v2)
)

// laneNFT is this engine's lane key into the DAO fee config.
const laneNFT = "nft"

// resolveFee reads the NFT-lane protocol fee (bps) and treasury from the DAO config
// realm. It is FAIL-SAFE (panel C1): the config getters are pure and non-failing, and
// on any implausible value the engine falls back to its own constants rather than
// reverting a user's trade — a fee misconfig must never strand a settlement. The fee
// is clamped to [0, core.MaxFeeBPS] so a compromised config can't overcharge.
func resolveFee() (int64, address) {
	bps := int64(cfg.GetFeeBPS(laneNFT))
	if bps < 0 || bps > core.MaxFeeBPS {
		bps = FeeBPS // fallback to the engine's frozen default
	}
	treasury := cfg.GetTreasury()
	if treasury == "" {
		treasury = feeRecipient // fallback to the engine's local recipient
	}
	return bps, treasury
}

// ── Types ─────────────────────────────────────────────────────────────────────

// Listing represents a fixed-price sale order.
type Listing struct {
	CollectionID string
	TokenID      string
	Seller       address
	Price        int64
	CreatedBlk   int64
}

// Sale records a completed transaction for the salesLog.
type Sale struct {
	CollectionID string
	TokenID      string
	Seller       address
	Buyer        address
	Price        int64
	Fee          int64
	Royalty      int64
	Blk          int64
}

// ── State ─────────────────────────────────────────────────────────────────────

var (
	listings     *avl.Tree // listingKey -> *Listing
	offers       *avl.Tree // offerKey   -> *Offer
	salesLog     *avl.Tree // itoa(saleId) -> *Sale
	listingOrder []string  // insertion-ordered listing keys (pagination)
	nextSaleId   int64
	totalVolume  int64
	paused       bool
	feeRecipient = address(AdminAddress)
)

func init() {
	listings = avl.NewTree()
	offers = avl.NewTree()
	salesLog = avl.NewTree()
}

// ── Key helpers ───────────────────────────────────────────────────────────────

func listingKey(collectionID, tokenID string) string {
	return collectionID + ":" + tokenID
}

func offerKey(collectionID, tokenID string, buyer address) string {
	return collectionID + ":" + tokenID + ":" + string(buyer)
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// sumUgnot returns the total ugnot in a coin set.
func sumUgnot(coins chain.Coins) int64 {
	for _, c := range coins {
		if c.Denom == "ugnot" {
			return c.Amount
		}
	}
	return 0
}

// removeFromOrder removes a key from the ordered listing slice (O(n)).
func removeFromOrder(key string) {
	for i, k := range listingOrder {
		if k == key {
			listingOrder = append(listingOrder[:i], listingOrder[i+1:]...)
			return
		}
	}
}

// countListingsBySeller counts a seller's open listings. Bounded by MaxListings.
func countListingsBySeller(seller address) int {
	n := 0
	listings.Iterate("", "", func(_ string, v interface{}) bool {
		if v.(*Listing).Seller == seller {
			n++
		}
		return false
	})
	return n
}

// countOffersByBuyer counts a buyer's open offers. Bounded by MaxOffers.
func countOffersByBuyer(buyer address) int {
	n := 0
	offers.Iterate("", "", func(_ string, v interface{}) bool {
		if v.(*Offer).Buyer == buyer {
			n++
		}
		return false
	})
	return n
}

// ── List / Delist ─────────────────────────────────────────────────────────────

// ListNFT lists an NFT for fixed-price sale.
// PREREQUISITE: Owner must call memba_collections.SetApprovalForAll(collectionID,
// marketplace, true) first so MarketTransfer can execute on behalf of the seller.
func ListNFT(cur realm, collectionID string, tid grc721.TokenID, price int64) {
	if paused {
		panic("market paused")
	}
	seller := unsafe.PreviousRealm().Address()

	if price < MinPrice {
		panic(ufmt.Sprintf("price must be >= %d ugnot", MinPrice))
	}
	if price > MaxPrice {
		panic(ufmt.Sprintf("price must be <= %d ugnot", MaxPrice))
	}
	if listings.Size() >= MaxListings {
		panic("marketplace listing limit reached")
	}
	if countListingsBySeller(seller) >= MaxListingsPerAddr {
		panic("seller listing limit reached")
	}

	key := listingKey(collectionID, string(tid))
	if _, exists := listings.Get(key); exists {
		panic("already listed: " + key)
	}

	// Effects
	listings.Set(key, &Listing{
		CollectionID: collectionID,
		TokenID:      string(tid),
		Seller:       seller,
		Price:        price,
		CreatedBlk:   runtime.ChainHeight(),
	})
	listingOrder = append(listingOrder, key)

	chain.Emit("NFTListed",
		"collection", collectionID,
		"tokenId", string(tid),
		"seller", seller.String(),
		"price", itoa(price),
	)
}

// DelistNFT removes a listing. Only the original lister can delist. Pause-exempt
// (value-exit: unwinds the seller's position).
func DelistNFT(cur realm, collectionID string, tid grc721.TokenID) {
	caller := unsafe.PreviousRealm().Address()
	key := listingKey(collectionID, string(tid))

	val, exists := listings.Get(key)
	if !exists {
		panic("not listed: " + key)
	}
	l := val.(*Listing)
	if l.Seller != caller {
		panic("only seller can delist")
	}

	// Effects
	listings.Remove(key)
	removeFromOrder(key)

	chain.Emit("NFTDelisted",
		"collection", collectionID,
		"tokenId", string(tid),
		"seller", caller.String(),
	)
}

// ── Buy ───────────────────────────────────────────────────────────────────────

// BuyNFT purchases a listed NFT atomically (CEI order).
//
// CEI:
//   Checks  — paused / IsUserCall / listed / self-buy / payment amount
//   Effects — remove listing from state, record sale, update volume
//   Interactions — cross-call MarketTransfer, then banker payouts (seller last)
func BuyNFT(cur realm, collectionID string, tid grc721.TokenID) {
	if paused {
		panic("market paused")
	}
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("must be a direct user call")
	}
	key := listingKey(collectionID, string(tid))
	v, ok := listings.Get(key)
	if !ok {
		panic("listing not found")
	}
	l := v.(*Listing)
	buyer := unsafe.PreviousRealm().Address()
	if buyer == l.Seller {
		panic("cannot buy own listing")
	}
	if sumUgnot(unsafe.OriginSend()) != l.Price {
		panic("incorrect payment")
	}

	royRecip, royAmt := nft.RoyaltyInfo(collectionID, tid, l.Price)
	// v3.1: per-lane fee + treasury from the DAO config spine (fail-safe), settled via
	// the shared SplitProceedsBPS money-math.
	feeBps, treasury := resolveFee()
	fee, royalty, sellerAmt := core.SplitProceedsBPS(l.Price, feeBps, royAmt)

	// Effects (before cross-call + sends)
	seller := l.Seller
	price := l.Price
	listings.Remove(key)
	removeFromOrder(key)
	recordSale(collectionID, string(tid), seller, buyer, price, fee, royalty)
	totalVolume += price

	// Interactions
	nft.MarketTransfer(cross(cur), collectionID, seller, buyer, tid)
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := unsafe.CurrentRealm().Address()
	if royalty > 0 {
		bnk.SendCoins(self, royRecip, chain.Coins{chain.NewCoin("ugnot", royalty)})
	}
	if fee > 0 {
		bnk.SendCoins(self, treasury, chain.Coins{chain.NewCoin("ugnot", fee)})
	}
	bnk.SendCoins(self, seller, chain.Coins{chain.NewCoin("ugnot", sellerAmt)}) // seller last

	// v3 change #3: single canonical settlement event (via="buy").
	emitSale("buy", collectionID, string(tid), seller, buyer, price, fee, royalty, royRecip, sellerAmt, feeBps, treasury)
}

// ── emitSale ──────────────────────────────────────────────────────────────────

// emitSale emits the ONE canonical settlement event for a completed sale.
// v3 change #3: replaces v2's split PurchaseConfirmed / (OfferAccepted + TokenSold)
// events with a single `Sale` event keyed by `via` ("buy" | "offer"), so indexers
// count each sale exactly once. v3 change #2: carries the payment `denom`.
// v3.1: the event now also carries the `feeBps` and `treasury` ACTUALLY used for this
// settlement (read from the DAO config at settlement time), so the indexer and audit
// trail are authoritative even across a DAO fee/treasury change (panel M3).
func emitSale(via, collectionID, tokenID string, seller, buyer address, price, fee, royalty int64, royRecip address, sellerAmt, feeBps int64, treasury address) {
	chain.Emit("Sale",
		"via", via,
		"collection", collectionID,
		"tokenId", tokenID,
		"seller", seller.String(),
		"buyer", buyer.String(),
		"price", itoa(price),
		"fee", itoa(fee),
		"royalty", itoa(royalty),
		"royaltyRecipient", royRecip.String(),
		"sellerAmount", itoa(sellerAmt),
		"denom", SettlementDenom,
		"feeBps", itoa(feeBps),
		"treasury", treasury.String(),
		// schemaVersion last, per the memba_market_core_v2 event contract — lets the
		// indexer branch parsing deterministically (review finding H1).
		"schemaVersion", core.SchemaVersion,
	)
}

// v3.1: the three-way split now lives in p/samcrew/memba_market_core_v2 (SplitProceedsBPS),
// taking the per-lane fee bps so every engine shares one audited money-math
// implementation. The old local splitProceeds (hardcoded FeeBPS) was removed.

// ── recordSale ────────────────────────────────────────────────────────────────

func recordSale(collectionID, tokenID string, seller, buyer address, price, fee, royalty int64) {
	nextSaleId++
	salesLog.Set(itoa(nextSaleId), &Sale{
		CollectionID: collectionID,
		TokenID:      tokenID,
		Seller:       seller,
		Buyer:        buyer,
		Price:        price,
		Fee:          fee,
		Royalty:      royalty,
		Blk:          runtime.ChainHeight(),
	})
}

// ── IsPaused ─────────────────────────────────────────────────────────────────

func IsPaused() bool { return paused }

// ── truncAddr / truncPath (render helpers) ────────────────────────────────────

func truncAddr(addr address) string {
	s := string(addr)
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

func truncPath(path string) string {
	parts := strings.Split(path, "/")
	if len(parts) > 2 {
		return parts[len(parts)-1]
	}
	return path
}

package memba_nft_market_v3_1

// Offer management — escrowed buyer offers on any listed NFT.
//
// Lifecycle:
//   MakeOffer      — buyer sends ugnot, funds held in escrow by this realm
//   CancelOffer    — buyer cancels (pause-exempt; must wait MinOfferLifetimeBlk)
//   AcceptOffer    — listing seller accepts; settles atomically via MarketTransfer + payouts
//   ClaimExpiredOffer — anyone claims refund after OfferTimeoutBlk (safety valve)
//
// Pause policy: MakeOffer + AcceptOffer are blocked while paused (new escrow /
// new settlement). CancelOffer + ClaimExpiredOffer are pause-exempt (value-exit).
//
// PHASE 3+ (deferred): collection-wide offers (an offer that matches ANY token in a
// collection rather than a specific token id) are NOT built here — see the deferred
// list in market.gno. This engine only supports per-token offers.

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/samcrew/grc721"
	"gno.land/p/nt/ufmt/v0"

	core "gno.land/p/samcrew/memba_market_core_v2" // v3.1: shared per-lane fee math
	nft "gno.land/r/samcrew/memba_collections"  // v3 change #4: canonical registry (was memba_nft_v2)
)

// Offer is an escrowed buy proposal on a specific (collection, token) pair.
type Offer struct {
	CollectionID string
	TokenID      string
	Buyer        address
	Amount       int64 // ugnot held in escrow
	CreatedBlk   int64
}

// MakeOffer places an offer with escrowed funds.
// Caller must send ugnot with the transaction; funds are held by this realm.
func MakeOffer(cur realm, collectionID string, tid grc721.TokenID) {
	if paused {
		panic("market paused")
	}
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("must be a direct user call")
	}
	buyer := unsafe.PreviousRealm().Address()
	amt := sumUgnot(unsafe.OriginSend())
	if amt < MinPrice {
		panic("offer below minimum")
	}

	if offers.Size() >= MaxOffers {
		panic("offer limit reached")
	}
	if countOffersByBuyer(buyer) >= MaxOffersPerAddr {
		panic("buyer offer limit reached")
	}

	key := offerKey(collectionID, string(tid), buyer)
	if _, exists := offers.Get(key); exists {
		panic("offer already exists, cancel first")
	}

	// Effects
	offers.Set(key, &Offer{
		CollectionID: collectionID,
		TokenID:      string(tid),
		Buyer:        buyer,
		Amount:       amt,
		CreatedBlk:   runtime.ChainHeight(),
	})

	chain.Emit("OfferMade",
		"collection", collectionID,
		"tokenId", string(tid),
		"buyer", buyer.String(),
		"amount", itoa(amt),
	)
}

// CancelOffer allows the offerer to reclaim escrowed funds.
// Pause-exempt (value-exit). Must wait MinOfferLifetimeBlk to prevent front-run.
func CancelOffer(cur realm, collectionID string, tid grc721.TokenID) {
	caller := unsafe.PreviousRealm().Address()
	key := offerKey(collectionID, string(tid), caller)

	val, exists := offers.Get(key)
	if !exists {
		panic("offer not found")
	}
	o := val.(*Offer)

	age := runtime.ChainHeight() - o.CreatedBlk
	if age < MinOfferLifetimeBlk {
		panic(ufmt.Sprintf("offer too new to cancel: %d blocks remaining", MinOfferLifetimeBlk-age))
	}

	// Effects
	amt := o.Amount
	offers.Remove(key)

	// Interactions
	refund(cur, caller, amt)

	chain.Emit("OfferCancelled",
		"collection", collectionID,
		"tokenId", string(tid),
		"buyer", caller.String(),
		"amount", itoa(amt),
	)
}

// ClaimExpiredOffer returns escrowed funds when an offer has exceeded OfferTimeoutBlk.
// Pause-exempt (safety-valve: prevents permanent escrow lock).
// Anyone can call on behalf of the buyer, but funds always go to the buyer.
func ClaimExpiredOffer(cur realm, collectionID string, tid grc721.TokenID, buyer address) {
	key := offerKey(collectionID, string(tid), buyer)

	val, exists := offers.Get(key)
	if !exists {
		panic("offer not found")
	}
	o := val.(*Offer)

	age := runtime.ChainHeight() - o.CreatedBlk
	if age < OfferTimeoutBlk {
		panic(ufmt.Sprintf("offer not yet expired: %d blocks remaining", OfferTimeoutBlk-age))
	}

	// Effects
	amt := o.Amount
	offers.Remove(key)

	// Interactions
	refund(cur, buyer, amt)

	chain.Emit("OfferExpiredClaimed",
		"collection", collectionID,
		"tokenId", string(tid),
		"buyer", buyer.String(),
		"amount", itoa(amt),
	)
}

// AcceptOffer allows the listing seller to accept a buyer's escrowed offer.
// Requires an active listing (seller must have listed first).
// Settles atomically: cross-call MarketTransfer then pay royalty, fee, seller (seller last).
func AcceptOffer(cur realm, collectionID string, tid grc721.TokenID, buyer address) {
	if paused {
		panic("market paused")
	}
	seller := unsafe.PreviousRealm().Address()

	listKey := listingKey(collectionID, string(tid))
	lv, listed := listings.Get(listKey)
	if !listed {
		panic("AcceptOffer requires an active listing — list the NFT first")
	}
	l := lv.(*Listing)
	if l.Seller != seller {
		panic("only the listing seller can accept offers")
	}

	if buyer == seller {
		panic("cannot accept own offer")
	}

	oKey := offerKey(collectionID, string(tid), buyer)
	ov, exists := offers.Get(oKey)
	if !exists {
		panic("offer not found")
	}
	o := ov.(*Offer)

	royRecip, royAmt := nft.RoyaltyInfo(collectionID, tid, o.Amount)
	// v3.1: per-lane fee + treasury from the DAO config spine (fail-safe), shared math.
	feeBps, treasury := resolveFee()
	fee, royalty, sellerAmt := core.SplitProceedsBPS(o.Amount, feeBps, royAmt)

	// Effects (before cross-call + sends)
	amt := o.Amount
	offers.Remove(oKey)
	listings.Remove(listKey)
	removeFromOrder(listKey)
	recordSale(collectionID, string(tid), seller, buyer, amt, fee, royalty)
	totalVolume += amt

	// Interactions
	nft.MarketTransfer(cross(cur), collectionID, seller, buyer, tid)
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := unsafe.CurrentRealm().Address()
	if royalty > 0 {
		bnk.SendCoins(self, royRecip, chain.Coins{chain.NewCoin("ugnot", royalty)})
	}
	if fee > 0 {
		bnk.SendCoins(self, treasury, chain.Coins{chain.NewCoin("ugnot", fee)})
	}
	bnk.SendCoins(self, seller, chain.Coins{chain.NewCoin("ugnot", sellerAmt)}) // seller last

	// v3 change #3: ONE canonical settlement event (via="offer"). v2 emitted BOTH
	// OfferAccepted AND TokenSold here, double-counting the sale in indexers.
	emitSale("offer", collectionID, string(tid), seller, buyer, amt, fee, royalty, royRecip, sellerAmt, feeBps, treasury)
}

// refund sends escrowed ugnot back to a recipient from this realm's balance.
func refund(cur realm, to address, amt int64) {
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(unsafe.CurrentRealm().Address(), to, chain.Coins{chain.NewCoin("ugnot", amt)})
}

package memba_nft_market_v3_1

// Platform constants — single source of truth for all fee math and caps.

const (
	FeeBPS             = int64(200)                   // v3 change #1: 2.0% platform fee (was 2.5% / 250 bps in v2)
	MaxRoyaltyBPS      = int64(1000)                  // 10% maximum royalty (defense-in-depth clamp)
	MinPrice           = int64(1000)                  // 0.001 GNOT — prevents fee truncation to zero
	MaxPrice           = int64(1_000_000_000_000_000) // 1 billion GNOT
	OfferTimeoutBlk    = int64(302400)                // ~7 days at 2 s/block
	MinOfferLifetimeBlk = int64(10)                   // offer must live ≥ 10 blocks before cancel
	MaxListings        = 1000
	MaxOffers          = 1000
	MaxListingsPerAddr = 50
	MaxOffersPerAddr   = 50
	AdminAddress       = "g1x7k4628w93a7wzdhqc06atzx0v50rnshweuxu0"

	// v3 change #2: settlement payment denom. Carried on every settlement event for
	// forward-compat with the GRC20 settlement desk (PHASE 3+). Today, the engine
	// only settles in ugnot.
	SettlementDenom = "ugnot"
)

package memba_nft_market_v3_1

// Render — public read-only views.
//
// Routes:
//   ""       — home: active listings count + volume
//   "stats"  — platform fee, totals
//   "sales"  — recent sales (up to 20)
//   *        — 404

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	switch path {
	case "":
		return renderHome()
	case "stats":
		return renderStats()
	case "sales":
		return renderSales()
	default:
		return "# 404\nNot found: " + path
	}
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# NFT Marketplace\n\n")
	sb.WriteString(ufmt.Sprintf("**Active Listings:** %d\n", listings.Size()))
	volGnot := ufmt.Sprintf("%d.%06d", totalVolume/1_000_000, totalVolume%1_000_000)
	sb.WriteString(ufmt.Sprintf("**Total Volume:** %s GNOT\n", volGnot))

	if len(listingOrder) == 0 {
		sb.WriteString("\n*No active listings.*\n")
		return sb.String()
	}

	const homePageCap = 50

	sb.WriteString("\n| # | Collection | Token | Price | Seller |\n")
	sb.WriteString("|---|-----------|-------|-------|--------|\n")
	shown := 0
	for i, key := range listingOrder {
		if shown >= homePageCap {
			break
		}
		val, exists := listings.Get(key)
		if !exists {
			continue
		}
		l := val.(*Listing)
		priceGnot := ufmt.Sprintf("%d.%06d", l.Price/1_000_000, l.Price%1_000_000)
		sb.WriteString(ufmt.Sprintf("| %d | %s | %s | %s GNOT | %s |\n",
			i+1, truncPath(l.CollectionID), l.TokenID, priceGnot, truncAddr(l.Seller)))
		shown++
	}
	if len(listingOrder) > homePageCap {
		sb.WriteString(ufmt.Sprintf("\n*… showing first %d of %d listings.*\n", homePageCap, len(listingOrder)))
	}
	return sb.String()
}

// feePctString renders FeeBPS as a percent with two decimals (e.g. 200 bps -> "2.00").
// gno's ufmt parses width digits but drops the zero-pad flag, so "%02d" does NOT
// zero-pad — pad the fractional bps explicitly.
func feePctString() string {
	whole := FeeBPS / 100
	frac := FeeBPS % 100
	if frac < 10 {
		return ufmt.Sprintf("%d.0%d", whole, frac)
	}
	return ufmt.Sprintf("%d.%d", whole, frac)
}

func renderStats() string {
	var sb strings.Builder
	sb.WriteString("# Marketplace Stats\n\n")
	sb.WriteString(ufmt.Sprintf("**Active Listings:** %d\n", listings.Size()))
	sb.WriteString(ufmt.Sprintf("**Total Sales:** %d\n", salesLog.Size()))
	volGnot := ufmt.Sprintf("%d.%06d", totalVolume/1_000_000, totalVolume%1_000_000)
	sb.WriteString(ufmt.Sprintf("**Total Volume:** %s GNOT\n", volGnot))
	sb.WriteString(ufmt.Sprintf("**Active Offers:** %d\n", offers.Size()))
	sb.WriteString(ufmt.Sprintf("**Platform Fee:** %s%%\n", feePctString()))
	sb.WriteString(ufmt.Sprintf("**Max Royalty:** %d%%\n", MaxRoyaltyBPS/100))
	return sb.String()
}

func renderSales() string {
	var sb strings.Builder
	sb.WriteString("# Recent Sales\n\n")
	if salesLog.Size() == 0 {
		sb.WriteString("*No sales yet.*\n")
		return sb.String()
	}

	sb.WriteString("| Sale | Collection | Token | Price | Seller | Buyer |\n")
	sb.WriteString("|------|-----------|-------|-------|--------|-------|\n")

	count := 0
	salesLog.ReverseIterate("", "", func(key string, val interface{}) bool {
		s := val.(*Sale)
		priceGnot := ufmt.Sprintf("%d.%06d", s.Price/1_000_000, s.Price%1_000_000)
		sb.WriteString(ufmt.Sprintf("| %s | %s | %s | %s GNOT | %s | %s |\n",
			key, truncPath(s.CollectionID), s.TokenID, priceGnot,
			truncAddr(s.Seller), truncAddr(s.Buyer)))
		count++
		return count >= 20
	})
	return sb.String()
}

package escrow_v3

// Milestone-based Escrow — On-chain freelance service contracts for Memba.
//
// Flow: CreateContract → FundMilestone → CompleteMilestone → ReleaseFunds
// Disputes: RaiseDispute → admin resolves (or auto-resolves after timeout)
// Timeouts: ClaimRefund (auto-refund if milestone not completed after N blocks)
//           ClaimDisputeTimeout (auto-release to freelancer if admin doesn't act)
//
// Security:
//   - STATE-BEFORE-SEND: All state updates happen before SendCoins calls
//   - FeeRecipient validated in init()
//   - Self-hire prevention: freelancer != client
//   - Input validation: title/description length, milestone amounts > 0
//   - Auto-refund: prevents permanent fund locking
//   - Dispute timeout: prevents permanent dispute locking
//
// Render() contract:
//   Home — Render(""):
//     # Escrow Contracts
//     | ID | Title | Client | Freelancer | Status | Total |
//
//   Detail — Render("contract/ID"):
//     # Title
//     **Client:** g1...
//     **Freelancer:** g1...
//     **Status:** active
//     ## Milestones
//     - **Milestone Title** — 1000000 ugnot [funded]

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"

	cfg "gno.land/r/samcrew/memba_market_config"
)

// ── Constants ────────────────────────────────────────────────

// laneService is this engine's lane key into the DAO fee spine (memba_market_config).
// Seeded there at 200 bps (2.0%) — see memba_market_config/config.gno's init(), which
// explicitly documents "service" as escrow's release fee lane.
const laneService = "service"

const (
	AdminAddress    = "g1x7k4628w93a7wzdhqc06atzx0v50rnshweuxu0" // samcrew-core-test1 multisig
	// FeeRecipient is now only the FAIL-SAFE fallback (see resolveFee below) for when
	// memba_market_config is unreachable — the live path reads cfg.GetTreasury().
	FeeRecipient    = "g1x7k4628w93a7wzdhqc06atzx0v50rnshweuxu0" // Samourai Coop multisig
	// PlatformFeePct is now only the FAIL-SAFE fallback bps source (see resolveFee) —
	// the live path reads cfg.GetFeeBPS(laneService). Kept as a 0-100 percent (not bps)
	// for backward-compat readability; resolveFee converts it.
	PlatformFeePct  = 2  // 2% fallback only
	CancelFeePct    = 5  // 5% cancellation fee — escrow-internal, NOT on the fee spine
	                     // (paid to the freelancer as compensation, not a protocol fee)
	AutoRefundBlks  = int64(864000)  // ~30 days at 3s/block
	AutoResolveBlks = int64(806400)  // ~28 days at 3s/block
	MaxTitleLen        = 200
	MaxDescLen         = 5000
	MaxMilestones      = 20
	MaxContracts       = 500
	MinMilestoneAmount = int64(1000) // 0.001 GNOT — prevents fee evasion via truncation
)

// ── Types ────────────────────────────────────────────────────

type ContractStatus string

const (
	StatusActive    ContractStatus = "active"
	StatusCompleted ContractStatus = "completed"
	StatusDisputed  ContractStatus = "disputed"
	StatusCancelled ContractStatus = "cancelled"
)

type MilestoneStatus string

const (
	MsPending   MilestoneStatus = "pending"
	MsFunded    MilestoneStatus = "funded"
	MsCompleted MilestoneStatus = "completed"
	MsReleased  MilestoneStatus = "released"
	MsDisputed  MilestoneStatus = "disputed"
	MsRefunded  MilestoneStatus = "refunded"
)

type Contract struct {
	ID          string
	Client      address
	Freelancer  address
	Title       string
	Description string
	Status      ContractStatus
	CreatedAt   int64 // block height
	Milestones  []Milestone
}

type Milestone struct {
	ID               int
	Title            string
	Amount           int64 // ugnot
	Status           MilestoneStatus
	FundedAt         int64           // block height (0 if not funded)
	CompletedAt      int64           // block height (0 if not completed)
	DisputedAt       int64           // block height (0 if not disputed)
	PreDisputeStatus MilestoneStatus // status before dispute (MsFunded or MsCompleted)
}

// ── State ────────────────────────────────────────────────────

var (
	contracts   *avl.Tree // id -> *Contract
	nextID      int
	paused      bool
	totalLiable int64 // NF-2: ugnot owed to funded/disputed milestones — see getters.gno
)

func init() {
	contracts = avl.NewTree()

	// Validate FeeRecipient at init — prevents fund-trapping panics later
	if len(FeeRecipient) == 0 {
		panic("FeeRecipient cannot be empty")
	}
}

// resolveFee reads the "service" lane protocol fee (bps) and treasury from the DAO
// fee spine (memba_market_config), same fail-safe pattern as memba_nft_market_v3_2's
// resolveFee and memba_token_otc_v2's Fill: the config getters are pure and
// non-failing, and on any implausible value this falls back to the engine's own
// frozen constants rather than reverting a client's release/refund — a config
// misread must never strand escrowed funds.
func resolveFee() (int64, address) {
	bps := int64(cfg.GetFeeBPS(laneService))
	if bps < 0 || bps > cfg.MaxFeeBPS {
		bps = int64(PlatformFeePct) * 100 // fallback, expressed in bps
	}
	treasury := cfg.GetTreasury()
	if treasury == "" {
		treasury = address(FeeRecipient) // fallback to the engine's local recipient
	}
	return bps, treasury
}

// ── Emergency Pause ────────────────────────────────────────

func assertNotPaused() {
	if paused {
		panic("realm is paused — emergency maintenance")
	}
}

// Pause halts all write operations. Admin only.
func Pause(cur realm) {
	caller := unsafe.PreviousRealm().Address()
	if caller != address(AdminAddress) {
		panic("only admin can pause")
	}
	paused = true
}

// Unpause resumes normal operations. Admin only.
func Unpause(cur realm) {
	caller := unsafe.PreviousRealm().Address()
	if caller != address(AdminAddress) {
		panic("only admin can unpause")
	}
	paused = false
}

// IsPaused returns the current pause state.
func IsPaused() bool {
	return paused
}

// ── Contract Lifecycle ──────────────────────────────────────

// CreateContract creates a new escrow contract with milestones.
// Milestones format: "title1:amount1,title2:amount2"
func CreateContract(cur realm, freelancer address, title, description, milestones string) string {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	// Validations
	if freelancer == caller {
		panic("cannot hire yourself")
	}
	if len(title) == 0 || len(title) > MaxTitleLen {
		panic(ufmt.Sprintf("title must be 1-%d characters", MaxTitleLen))
	}
	if len(description) > MaxDescLen {
		panic(ufmt.Sprintf("description must be under %d characters", MaxDescLen))
	}
	if contracts.Size() >= MaxContracts {
		panic("contract limit reached")
	}

	ms := parseMilestones(milestones)
	if len(ms) == 0 {
		panic("at least one milestone required")
	}
	if len(ms) > MaxMilestones {
		panic(ufmt.Sprintf("maximum %d milestones allowed", MaxMilestones))
	}

	id := strconv.Itoa(nextID)
	nextID++

	c := &Contract{
		ID:          id,
		Client:      caller,
		Freelancer:  freelancer,
		Title:       sanitizeMilestoneTitle(title),
		Description: sanitizeMilestoneTitle(description),
		Status:      StatusActive,
		CreatedAt:   runtime.ChainHeight(),
		Milestones:  ms,
	}
	contracts.Set(id, c)

	chain.Emit("ContractCreated",
		"id", id,
		"client", caller.String(),
		"freelancer", freelancer.String(),
		"milestones", strconv.Itoa(len(ms)),
	)
	return id
}

// FundMilestone deposits funds for a specific milestone. Client only.
func FundMilestone(cur realm, contractId string, milestoneIdx int) {
	assertNotPaused()

	// P0 fund-guard: a payable entrypoint MUST be a direct user call. unsafe.OriginSend()
	// reports the tx-level `--send`, credited to the DIRECT message target realm — not to
	// an inner realm reached via a cross-call. Without this guard an attacker funds a
	// milestone through their own intermediary realm (coins land there), the escrow marks
	// the milestone funded though it received nothing, then the attacker extracts real
	// pooled client funds via ReleaseFunds/ClaimRefund. Requiring a direct user call forces
	// this realm to be the message target, the one case where the OriginSend coins are its own.
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("FundMilestone must be a direct user call")
	}

	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Client != caller {
		panic("only client can fund")
	}
	if c.Status != StatusActive {
		panic("contract not active")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsPending {
		panic("milestone already funded or processed")
	}

	// Verify coins sent (accumulate to handle multi-entry defensively)
	sent := unsafe.OriginSend()
	sentAmount := int64(0)
	for _, coin := range sent {
		if coin.Denom == "ugnot" {
			sentAmount += coin.Amount
		}
	}
	if sentAmount != ms.Amount {
		panic(ufmt.Sprintf("must send exactly %d ugnot (sent %d)", ms.Amount, sentAmount))
	}

	ms.Status = MsFunded
	ms.FundedAt = runtime.ChainHeight()
	contracts.Set(contractId, c)
	totalLiable += ms.Amount

	chain.Emit("MilestoneFunded",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"amount", strconv.FormatInt(ms.Amount, 10),
	)
}

// CompleteMilestone marks a milestone as completed. Freelancer only.
func CompleteMilestone(cur realm, contractId string, milestoneIdx int) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Freelancer != caller {
		panic("only freelancer can mark complete")
	}
	// Only allow completion when contract is Active. Disputed contracts are frozen
	// until ResolveDispute/ClaimDisputeTimeout returns the contract to Active.
	if c.Status != StatusActive {
		panic("contract is " + string(c.Status) + " — cannot complete milestones during dispute")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsFunded {
		panic("milestone not funded")
	}

	ms.Status = MsCompleted
	ms.CompletedAt = runtime.ChainHeight()
	contracts.Set(contractId, c)

	chain.Emit("MilestoneCompleted",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"freelancer", caller.String(),
	)
}

// ReleaseFunds releases funds to freelancer after client approves. Client or Admin.
func ReleaseFunds(cur realm, contractId string, milestoneIdx int) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Client != caller && caller != address(AdminAddress) {
		panic("only client or admin can release")
	}
	// Only allow release when contract is Active. Disputed contracts are frozen
	// until ResolveDispute/ClaimDisputeTimeout returns the contract to Active.
	if c.Status != StatusActive {
		panic("contract is " + string(c.Status) + " — cannot release funds during dispute")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsCompleted {
		panic("milestone not completed")
	}

	// Calculate fees — read live from the DAO fee spine (fail-safe fallback inside).
	bps, treasury := resolveFee()
	platformAmount := (ms.Amount * bps) / 10000
	freelancerAmount := ms.Amount - platformAmount

	// STATE-BEFORE-SEND: update all state before any coin transfers
	ms.Status = MsReleased
	if allMilestonesReleased(c) {
		c.Status = StatusCompleted
	}
	contracts.Set(contractId, c)
	totalLiable -= ms.Amount

	// Transfer funds
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()

	bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", freelancerAmount)})
	if platformAmount > 0 {
		bnk.SendCoins(realmAddr, treasury, chain.Coins{chain.NewCoin("ugnot", platformAmount)})
	}

	chain.Emit("FundsReleased",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"freelancer", c.Freelancer.String(),
		"amount", strconv.FormatInt(freelancerAmount, 10),
		"fee", strconv.FormatInt(platformAmount, 10),
	)
}

// ── Disputes ────────────────────────────────────────────────

// RaiseDispute escalates a milestone to admin arbitration. Client or Freelancer.
func RaiseDispute(cur realm, contractId string, milestoneIdx int) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Client != caller && c.Freelancer != caller {
		panic("only client or freelancer can dispute")
	}
	if c.Status == StatusCancelled || c.Status == StatusCompleted {
		panic("contract is " + string(c.Status))
	}
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsFunded && ms.Status != MsCompleted {
		panic("can only dispute funded or completed milestones")
	}

	// Capture pre-dispute status so ClaimDisputeTimeout can resolve fairly:
	// if work was delivered (MsCompleted), pay freelancer; if not (MsFunded), refund client.
	ms.PreDisputeStatus = ms.Status
	ms.Status = MsDisputed
	ms.DisputedAt = runtime.ChainHeight()
	c.Status = StatusDisputed
	contracts.Set(contractId, c)

	chain.Emit("DisputeRaised",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"raisedBy", caller.String(),
	)
}

// ResolveDispute resolves a dispute. Admin only.
// refundClient=true refunds to client, false pays freelancer.
func ResolveDispute(cur realm, contractId string, milestoneIdx int, refundClient bool) {
	caller := unsafe.PreviousRealm().Address()
	if caller != address(AdminAddress) {
		panic("only admin can resolve disputes")
	}

	c := getContract(contractId)
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsDisputed {
		panic("milestone not in dispute")
	}

	// STATE-BEFORE-SEND: update state before transfers
	if refundClient {
		ms.Status = MsRefunded
	} else {
		ms.Status = MsReleased
	}
	// Reset contract status if no other milestones are disputed
	c.Status = StatusActive
	for _, m := range c.Milestones {
		if m.Status == MsDisputed {
			c.Status = StatusDisputed
			break
		}
	}
	if allMilestonesReleased(c) {
		c.Status = StatusCompleted
	}
	contracts.Set(contractId, c)
	totalLiable -= ms.Amount

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()

	if refundClient {
		bnk.SendCoins(realmAddr, c.Client, chain.Coins{chain.NewCoin("ugnot", ms.Amount)})
	} else {
		bps, treasury := resolveFee()
		platformAmount := (ms.Amount * bps) / 10000
		freelancerAmount := ms.Amount - platformAmount
		bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", freelancerAmount)})
		if platformAmount > 0 {
			bnk.SendCoins(realmAddr, treasury, chain.Coins{chain.NewCoin("ugnot", platformAmount)})
		}
	}

	resolution := "released-to-freelancer"
	if refundClient {
		resolution = "refunded-to-client"
	}
	chain.Emit("DisputeResolved",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"resolution", resolution,
	)
}

// ── Cancellation ────────────────────────────────────────────

// CancelContract cancels an active contract. Client only.
// Funded milestones are refunded minus cancellation fee.
func CancelContract(cur realm, contractId string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Client != caller {
		panic("only client can cancel")
	}
	if c.Status != StatusActive {
		panic("contract not active")
	}

	// STATE-BEFORE-SEND: update all state before transfers.
	// Track which milestones are NEWLY transitioned so we only pay those,
	// preventing double-refund of milestones already resolved via ResolveDispute.
	c.Status = StatusCancelled
	var newlyRefunded []int
	var newlyReleased []int
	for i := range c.Milestones {
		if c.Milestones[i].Status == MsFunded {
			c.Milestones[i].Status = MsRefunded
			newlyRefunded = append(newlyRefunded, i)
		} else if c.Milestones[i].Status == MsCompleted {
			c.Milestones[i].Status = MsReleased
			newlyReleased = append(newlyReleased, i)
		}
		// Already-terminal milestones (MsRefunded from ResolveDispute, MsReleased from
		// ReleaseFunds) are NOT added to the payment lists — their funds were already
		// distributed in the original operation.
	}
	contracts.Set(contractId, c)

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()

	for _, i := range newlyRefunded {
		ms := c.Milestones[i]
		// Refund funded milestones minus cancellation fee
		fee := (ms.Amount * int64(CancelFeePct)) / 100
		refund := ms.Amount - fee
		if refund > 0 {
			bnk.SendCoins(realmAddr, c.Client, chain.Coins{chain.NewCoin("ugnot", refund)})
		}
		// Cancellation fee goes to freelancer as compensation for lost opportunity
		// (escrow-internal, not on the DAO fee spine — see CancelFeePct doc comment).
		if fee > 0 {
			bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", fee)})
		}
		totalLiable -= ms.Amount
	}
	if len(newlyReleased) > 0 {
		bps, treasury := resolveFee()
		for _, i := range newlyReleased {
			ms := c.Milestones[i]
			// Pay freelancer for completed work (full amount minus platform fee)
			platformAmount := (ms.Amount * bps) / 10000
			freelancerAmount := ms.Amount - platformAmount
			bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", freelancerAmount)})
			if platformAmount > 0 {
				bnk.SendCoins(realmAddr, treasury, chain.Coins{chain.NewCoin("ugnot", platformAmount)})
			}
			totalLiable -= ms.Amount
		}
	}
}

// ── Timeouts (permissionless) ───────────────────────────────

// ClaimRefund refunds a funded milestone that has timed out.
// Anyone can call — permissionless, prevents fund locking.
func ClaimRefund(cur realm, contractId string, milestoneIdx int) {
	c := getContract(contractId)

	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsFunded {
		panic("milestone not funded")
	}
	if ms.FundedAt == 0 {
		panic("milestone has no funding record")
	}

	elapsed := runtime.ChainHeight() - ms.FundedAt
	if elapsed < AutoRefundBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", AutoRefundBlks-elapsed))
	}

	// STATE-BEFORE-SEND
	ms.Status = MsRefunded
	// Update contract status if all milestones are now terminal
	if allMilestonesTerminal(c) {
		c.Status = StatusCancelled
	}
	contracts.Set(contractId, c)
	totalLiable -= ms.Amount

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(
		unsafe.CurrentRealm().Address(),
		c.Client,
		chain.Coins{chain.NewCoin("ugnot", ms.Amount)},
	)
}

// ClaimDisputeTimeout auto-resolves a dispute that admin hasn't acted on after
// AutoResolveBlks (~28 days). Resolution follows the pre-dispute status:
//   - If the milestone was MsCompleted (freelancer delivered work) before dispute,
//     funds go to freelancer (minus platform fee). This prevents griefing where
//     a client disputes after delivery and simply waits out the clock.
//   - If the milestone was MsFunded (work not yet delivered) before dispute,
//     funds are refunded to client.
// Anyone can call (permissionless safety valve).
func ClaimDisputeTimeout(cur realm, contractId string, milestoneIdx int) {
	c := getContract(contractId)

	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsDisputed {
		panic("milestone not in dispute")
	}
	if ms.DisputedAt == 0 {
		panic("milestone has no dispute record")
	}

	elapsed := runtime.ChainHeight() - ms.DisputedAt
	if elapsed < AutoResolveBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", AutoResolveBlks-elapsed))
	}

	// Resolve based on pre-dispute status — fair to both parties.
	payFreelancer := ms.PreDisputeStatus == MsCompleted

	// STATE-BEFORE-SEND
	if payFreelancer {
		ms.Status = MsReleased
	} else {
		ms.Status = MsRefunded
	}
	// Reset contract status
	c.Status = StatusActive
	for _, m := range c.Milestones {
		if m.Status == MsDisputed {
			c.Status = StatusDisputed
			break
		}
	}
	if allMilestonesReleased(c) {
		c.Status = StatusCompleted
	} else if allMilestonesTerminal(c) {
		c.Status = StatusCancelled
	}
	contracts.Set(contractId, c)
	totalLiable -= ms.Amount

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()

	if payFreelancer {
		// Work was delivered — pay freelancer minus platform fee
		bps, treasury := resolveFee()
		platformAmount := (ms.Amount * bps) / 10000
		freelancerAmount := ms.Amount - platformAmount
		bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", freelancerAmount)})
		if platformAmount > 0 {
			bnk.SendCoins(realmAddr, treasury, chain.Coins{chain.NewCoin("ugnot", platformAmount)})
		}
		chain.Emit("DisputeTimedOut",
			"contractId", contractId,
			"milestone", strconv.Itoa(milestoneIdx),
			"resolution", "paid-freelancer-work-delivered",
		)
	} else {
		// Work never delivered — refund client in full
		bnk.SendCoins(realmAddr, c.Client, chain.Coins{chain.NewCoin("ugnot", ms.Amount)})
		chain.Emit("DisputeTimedOut",
			"contractId", contractId,
			"milestone", strconv.Itoa(milestoneIdx),
			"resolution", "refunded-client-no-delivery",
		)
	}
}

// ── Render ───────────────────────────────────────────────────

func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if strings.HasPrefix(path, "contract/") {
		id := strings.TrimPrefix(path, "contract/")
		return renderContract(id)
	}
	if path == "stats" {
		return renderStats()
	}
	return "# 404\nNot found: " + path
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# Escrow Contracts\n\n")
	sb.WriteString("Milestone-based escrow for freelance services on Gno.\n\n")

	if contracts.Size() == 0 {
		sb.WriteString("*No contracts yet.*\n")
		return sb.String()
	}

	sb.WriteString("| ID | Title | Client | Freelancer | Status | Total |\n")
	sb.WriteString("| --- | --- | --- | --- | --- | --- |\n")

	contracts.Iterate("", "", func(key string, value interface{}) bool {
		c := value.(*Contract)
		total := int64(0)
		for _, ms := range c.Milestones {
			total += ms.Amount
		}
		sb.WriteString(ufmt.Sprintf("| %s | [%s](:contract/%s) | %s | %s | %s | %d ugnot |\n",
			c.ID, c.Title, c.ID, truncAddr(c.Client), truncAddr(c.Freelancer),
			string(c.Status), total))
		return false
	})

	return sb.String()
}

func renderContract(id string) string {
	val, exists := contracts.Get(id)
	if !exists {
		return "# 404\nContract not found: " + id
	}
	c := val.(*Contract)

	var sb strings.Builder
	sb.WriteString("# " + c.Title + "\n\n")
	if len(c.Description) > 0 {
		sb.WriteString(c.Description + "\n\n")
	}
	sb.WriteString("**ID:** " + c.ID + "\n")
	sb.WriteString("**Client:** " + c.Client.String() + "\n")
	sb.WriteString("**Freelancer:** " + c.Freelancer.String() + "\n")
	sb.WriteString("**Status:** " + string(c.Status) + "\n")
	sb.WriteString("**Created:** block " + strconv.FormatInt(c.CreatedAt, 10) + "\n\n")

	total := int64(0)
	for _, ms := range c.Milestones {
		total += ms.Amount
	}
	sb.WriteString("**Total Value:** " + strconv.FormatInt(total, 10) + " ugnot\n\n")

	sb.WriteString("## Milestones\n\n")
	for _, ms := range c.Milestones {
		sb.WriteString(ufmt.Sprintf("- **%s** — %d ugnot [%s]",
			ms.Title, ms.Amount, string(ms.Status)))
		if ms.FundedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (funded block %d)", ms.FundedAt))
		}
		if ms.CompletedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (completed block %d)", ms.CompletedAt))
		}
		if ms.DisputedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (disputed block %d)", ms.DisputedAt))
		}
		sb.WriteString("\n")
	}

	return sb.String()
}

func renderStats() string {
	var sb strings.Builder
	sb.WriteString("# Escrow Stats\n\n")

	totalContracts := contracts.Size()
	active, completed, disputed, cancelled := 0, 0, 0, 0
	totalValue := int64(0)

	contracts.Iterate("", "", func(key string, value interface{}) bool {
		c := value.(*Contract)
		switch c.Status {
		case StatusActive:
			active++
		case StatusCompleted:
			completed++
		case StatusDisputed:
			disputed++
		case StatusCancelled:
			cancelled++
		}
		for _, ms := range c.Milestones {
			totalValue += ms.Amount
		}
		return false
	})

	sb.WriteString(ufmt.Sprintf("**Total Contracts:** %d\n", totalContracts))
	sb.WriteString(ufmt.Sprintf("**Active:** %d | **Completed:** %d | **Disputed:** %d | **Cancelled:** %d\n", active, completed, disputed, cancelled))
	sb.WriteString(ufmt.Sprintf("**Total Value:** %d ugnot\n", totalValue))

	return sb.String()
}

// ── Helpers ──────────────────────────────────────────────────

func getContract(id string) *Contract {
	val, exists := contracts.Get(id)
	if !exists {
		panic("contract not found: " + id)
	}
	return val.(*Contract)
}

func allMilestonesReleased(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status != MsReleased {
			return false
		}
	}
	return true
}

// allMilestonesTerminal returns true if every milestone is in a final state
// (released, refunded, or pending — pending with no funds is terminal).
func allMilestonesTerminal(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status == MsFunded || m.Status == MsCompleted || m.Status == MsDisputed {
			return false
		}
	}
	return true
}

// parseMilestones parses "title1:amount1,title2:amount2" into Milestone slice.
// Invalid entries cause a panic (not silently skipped).
func parseMilestones(input string) []Milestone {
	var result []Milestone
	parts := strings.Split(input, ",")
	for i, p := range parts {
		p = strings.TrimSpace(p)
		if len(p) == 0 {
			continue
		}
		kv := strings.SplitN(p, ":", 2)
		if len(kv) != 2 {
			panic(ufmt.Sprintf("invalid milestone format at position %d: expected 'title:amount'", i))
		}
		title := strings.TrimSpace(kv[0])
		if len(title) == 0 {
			panic(ufmt.Sprintf("empty milestone title at position %d", i))
		}
		if len(title) > MaxTitleLen {
			panic(ufmt.Sprintf("milestone title too long at position %d: %d/%d chars", i, len(title), MaxTitleLen))
		}
		title = sanitizeMilestoneTitle(title)
		amount, err := strconv.ParseInt(strings.TrimSpace(kv[1]), 10, 64)
		if err != nil || amount <= 0 {
			panic(ufmt.Sprintf("invalid milestone amount at position %d: must be positive integer", i))
		}
		// Minimum milestone amount prevents fee evasion via integer truncation.
		// At 2% fee, amounts < 50 ugnot would pay 0 fee.
		if amount < MinMilestoneAmount {
			panic(ufmt.Sprintf("milestone amount too small at position %d: minimum %d ugnot", i, MinMilestoneAmount))
		}
		result = append(result, Milestone{
			ID:     i,
			Title:  title,
			Amount: amount,
			Status: MsPending,
		})
	}
	return result
}

func truncAddr(addr address) string {
	s := addr.String()
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

// sanitizeMilestoneTitle strips markdown special characters to prevent injection
// in gnoweb Render output.
func sanitizeMilestoneTitle(s string) string {
	var out strings.Builder
	for _, c := range s {
		switch c {
		case '[', ']', '(', ')', '#', '*', '`', '!', '<', '>', '|', '\\', '_', '~', '\n', '\r', '\t':
			continue // strip markdown-sensitive characters and control whitespace
		default:
			out.WriteRune(c)
		}
	}
	return out.String()
}

package escrow_v3

// ── NF-2 solvency getters (MAINNET_READINESS.md §3) ───────────────────────────
//
// escrow_v3 pools funds between FundMilestone and release/refund, making it a
// pooled-fund realm. Without a machine-readable liabilities figure the solvency
// monitor can only do a balance-only heuristic. escrow_v3 was the LAST unpublished
// pooled-fund realm without this pair — candidature_v3 and agent_registry_v2
// already shipped on Topaz without it and can never get it now, on immutable
// package paths (§3b). Added before this realm ships to any enforce chain.
//
// Invariant the monitor reconciles: realm balance >= TotalLiabilities().
// totalLiable is maintained in lockstep with every fund-moving mutation in
// escrow.gno: +ms.Amount on FundMilestone, -ms.Amount at every point funds leave
// (ReleaseFunds; ResolveDispute both branches; CancelContract both branches;
// ClaimRefund; ClaimDisputeTimeout both branches) — see escrow_feespine_test.gno
// for the lockstep pin across every one of those paths.

import "chain/runtime/unsafe"

// TotalLiabilities returns the total ugnot the realm owes across all funded and
// disputed milestones (funds that have arrived but not yet left the realm).
func TotalLiabilities() int64 { return totalLiable }

// RealmAddress is the NF-2 canonical name for the realm's own address (the
// solvency monitor pairs it with TotalLiabilities).
func RealmAddress() string { return unsafe.CurrentRealm().Address().String() }

package memba_token_otc_v2

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/samcrew/memba_market_config"
	"gno.land/r/samcrew/tokenfactory_v2"
)

// AdminAddress is the same 2-of-2 multisig used by the market config.
const AdminAddress = "g10kw7e55e9wc8j8v6904ck29dqwr9fm9u280juh"

type Listing struct {
	Id        uint64
	Seller    address
	Symbol    string
	Amount    int64
	UnitPrice int64
	CreatedAt int64
}

var (
	admin         address
	paused        bool
	listings      avl.Tree // uint64 -> *Listing
	nextListingId uint64 = 1
)

func init() {
	admin = address(AdminAddress)
}

func caller() address { return unsafe.PreviousRealm().Address() }

// Pause acts as the kill switch for the engine (stops listing and filling).
func Pause(cur realm, state bool) {
	if caller() != admin {
		panic("unauthorized")
	}
	paused = state
}

// ListTokens creates a new OTC listing for a tokenfactory_v2 token.
func ListTokens(cur realm, symbol string, amount, unitPrice int64) uint64 {
	if paused {
		panic("engine is paused")
	}
	if amount <= 0 {
		panic("amount must be > 0")
	}
	if unitPrice <= 0 {
		panic("unitPrice must be > 0")
	}

	seller := caller()

	// SECURITY: Ensure the token was minted by tokenfactory_v2.
	// Bank will panic if the symbol is not registered in the factory.
	_ = tokenfactory_v2.Bank(symbol)

	// Verify the seller has enough balance and has approved this realm.
	bal := tokenfactory_v2.BalanceOf(symbol, seller)
	if bal < amount {
		panic("insufficient token balance")
	}
	allow := tokenfactory_v2.Allowance(symbol, seller, cur.Address())
	if allow < amount {
		panic("insufficient token allowance granted to OTC realm")
	}

	id := nextListingId
	nextListingId++

	listing := &Listing{
		Id:        id,
		Seller:    seller,
		Symbol:    symbol,
		Amount:    amount,
		UnitPrice: unitPrice,
		CreatedAt: runtime.ChainHeight(),
	}

	listings.Set(ufmt.Sprintf("%d", id), listing)

	chain.Emit("Listed",
		"id", ufmt.Sprintf("%d", id),
		"seller", string(seller),
		"symbol", symbol,
		"amount", ufmt.Sprintf("%d", amount),
		"unitPrice", ufmt.Sprintf("%d", unitPrice),
	)

	return id
}

// CancelListing removes an OTC listing. Only the seller can cancel.
func CancelListing(cur realm, listingId uint64) {
	seller := caller()
	listingRaw, exists := listings.Get(ufmt.Sprintf("%d", listingId))
	if !exists {
		panic("listing not found")
	}
	listing := listingRaw.(*Listing)

	if listing.Seller != seller {
		panic("unauthorized: not the seller")
	}

	listings.Remove(ufmt.Sprintf("%d", listingId))

	chain.Emit("Cancelled",
		"id", ufmt.Sprintf("%d", listingId),
	)
}

// Fill executes a partial or full fill of an OTC listing.
func Fill(cur realm, listingId uint64, qty, expectedUnitPrice int64) {
	if paused {
		panic("engine is paused")
	}

	// P0 fund-guard: a payable entrypoint MUST be a direct user call. unsafe.OriginSend()
	// reports the tx-level `--send`, credited to the DIRECT message target realm — not to
	// an inner realm reached via a cross-call. This realm forwards funds immediately and
	// holds no standing pool, so a routed fill self-reverts today (MED) — but the guard is
	// applied uniformly with the other payable entrypoints to close the residual-balance
	// edge (stranded/donated ugnot) and prevent regressions.
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("Fill must be a direct user call")
	}

	if qty <= 0 {
		panic("qty must be > 0")
	}

	buyer := caller()

	listingRaw, exists := listings.Get(ufmt.Sprintf("%d", listingId))
	if !exists {
		panic("listing not found")
	}
	listing := listingRaw.(*Listing)

	// Slippage & front-run protection
	if listing.UnitPrice != expectedUnitPrice {
		panic("price mismatch (front-run protection)")
	}

	if listing.Amount < qty {
		panic("requested qty exceeds available listing amount")
	}

	// Verify seller still has balance and allowance
	bal := tokenfactory_v2.BalanceOf(listing.Symbol, listing.Seller)
	if bal < qty {
		panic("seller has insufficient balance")
	}
	allow := tokenfactory_v2.Allowance(listing.Symbol, listing.Seller, cur.Address())
	if allow < qty {
		panic("seller has insufficient allowance")
	}

	// Calculate cost — guard the int64 multiplication against overflow. qty>0 (checked
	// above) and unitPrice>0 (checked at ListTokens), so a valid product is >0 and
	// cost/qty == unitPrice; a wrapped product fails one of those.
	cost := qty * listing.UnitPrice
	if cost <= 0 || cost/qty != listing.UnitPrice {
		panic("cost overflow")
	}

	// Dust-fill evasion protection (e.g., minimum notional > 0 if fee > 0)
	feeBps, treasury := memba_market_config.GetLaneConfig("token")
	if feeBps > int(memba_market_config.MaxFeeBPS) {
		feeBps = int(memba_market_config.DefaultFeeBPS) // safe fallback clamp
	}

	fee := (cost * int64(feeBps)) / 10000
	if feeBps > 0 && fee == 0 {
		panic("dust fill: notional too small to cover minimum fee")
	}

	// Require EXACT payment sent WITH this call. Read OriginSend (the coins attached to
	// the call) — NOT the caller's wallet balance — mirroring escrow_v2.FundMilestone.
	// Exact-coin closes both the overpay-trap (excess had no refund/sweep) and the
	// wallet-balance bypass (a funded caller could trigger a payout without paying).
	sent := unsafe.OriginSend()
	if sent.AmountOf("ugnot") != cost {
		panic(ufmt.Sprintf("must send exactly %d ugnot (sent %d)", cost, sent.AmountOf("ugnot")))
	}

	// CEI: Update state first
	listing.Amount -= qty
	if listing.Amount == 0 {
		listings.Remove(ufmt.Sprintf("%d", listingId))
	} else {
		listings.Set(ufmt.Sprintf("%d", listingId), listing)
	}

	// Route funds from the realm's own account (holding the exact ugnot just received).
	sellerProceeds := cost - fee
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()
	if fee > 0 {
		bnk.SendCoins(realmAddr, treasury, chain.Coins{chain.NewCoin("ugnot", fee)})
	}
	if sellerProceeds > 0 {
		bnk.SendCoins(realmAddr, listing.Seller, chain.Coins{chain.NewCoin("ugnot", sellerProceeds)})
	}

	// Transfer tokens and measure delta (fee-on-transfer protection)
	buyerBalBefore := tokenfactory_v2.BalanceOf(listing.Symbol, buyer)

	tokenfactory_v2.TransferFrom(cross(cur), listing.Symbol, listing.Seller, buyer, qty)

	buyerBalAfter := tokenfactory_v2.BalanceOf(listing.Symbol, buyer)
	delta := buyerBalAfter - buyerBalBefore
	if delta != qty {
		panic("token transfer delta mismatch (fee-on-transfer not supported)")
	}

	chain.Emit("Filled",
		"id", ufmt.Sprintf("%d", listingId),
		"buyer", string(buyer),
		"seller", string(listing.Seller),
		"symbol", listing.Symbol,
		"qty", ufmt.Sprintf("%d", qty),
		"unitPrice", ufmt.Sprintf("%d", listing.UnitPrice),
		"feeBps", ufmt.Sprintf("%d", feeBps),
		"fee", ufmt.Sprintf("%d", fee),
	)
}

// ── Read Getters ─────────────────────────────────────────────────────────────

// EngineAddress returns this realm's on-chain address — the account sellers approve to
// move their tokens and the settlement account. Exposed so the frontend/deploy ceremony
// can wire the engine without hardcoding the derived address (mirrors nft_market_v3
// MarketAddress()).
func EngineAddress() address {
	return unsafe.CurrentRealm().Address()
}

func GetListing(listingId uint64) *Listing {
	listingRaw, exists := listings.Get(ufmt.Sprintf("%d", listingId))
	if !exists {
		return nil
	}
	return listingRaw.(*Listing)
}

// Note: In production we'd want paginated getters here to prevent O(N) gas limits.
// For v1.1, we'll return all active listings or window them.
func GetListings() []*Listing {
	var result []*Listing
	listings.Iterate("", "", func(key string, value interface{}) bool {
		result = append(result, value.(*Listing))
		return false
	})
	return result
}

// GetListingsCSV returns listings formatted as "ID|Seller|Symbol|UnitPrice|Amount,ID|..."
// to avoid the frontend needing to parse raw Amino struct outputs.
func GetListingsCSV() string {
	out := ""
	listings.Iterate("", "", func(key string, value interface{}) bool {
		l := value.(*Listing)
		row := ufmt.Sprintf("%d|%s|%s|%d|%d", l.Id, string(l.Seller), l.Symbol, l.UnitPrice, l.Amount)
		if out == "" {
			out = row
		} else {
			out += "," + row
		}
		return false
	})
	return out
}

package memba_nft_market_v3_2

// Admin operations — multisig-gated controls.
//
// assertAdmin() is the single authorization gate; caller = unsafe.PreviousRealm().Address().
// AdminDelist is pause-exempt (moderation can always remove content).
// SetFeeRecipient changes where platform fees flow (default = AdminAddress).

import (
	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/samcrew/grc721"
)

func assertAdmin() {
	if unsafe.PreviousRealm().Address() != owner {
		panic("admin only")
	}
}

// Pause halts new trade operations (ListNFT, BuyNFT, MakeOffer, AcceptOffer).
// Value-exit paths (DelistNFT, CancelOffer, ClaimExpiredOffer) remain available.
func Pause(cur realm) {
	assertAdmin()
	paused = true
	chain.Emit("MarketPaused", "by", unsafe.PreviousRealm().Address().String())
}

// Unpause resumes normal operations.
func Unpause(cur realm) {
	assertAdmin()
	paused = false
	chain.Emit("MarketUnpaused", "by", unsafe.PreviousRealm().Address().String())
}

// AdminDelist force-removes any listing. Pause-exempt (moderation).
func AdminDelist(cur realm, collectionID string, tid grc721.TokenID) {
	assertAdmin()
	key := listingKey(collectionID, string(tid))
	if _, exists := listings.Get(key); !exists {
		panic("not listed: " + key)
	}
	listings.Remove(key)
	removeFromOrder(key)
	chain.Emit("AdminDelisted",
		"collection", collectionID,
		"tokenId", string(tid),
		"admin", unsafe.PreviousRealm().Address().String(),
	)
}

// SetFeeRecipient updates the address that receives platform fees. Rejects the
// empty address: resolveFee falls back to feeRecipient when the DAO config
// treasury is unset, and a fee send to "" panics — with both unset, every
// trade with a nonzero fee would revert (fat-finger brick, pre-deploy review).
func SetFeeRecipient(cur realm, addr address) {
	assertAdmin()
	if addr == "" {
		panic("fee recipient must be non-empty")
	}
	feeRecipient = addr
	chain.Emit("FeeRecipientChanged", "newRecipient", addr.String())
}

// ── Ownership (2-step, pre-deploy review) ─────────────────────────────────────
//
// The admin used to be a hard-coded constant — on an immutable realm that means
// the engine could never be handed to a DAO executor without a full redeploy.
// 2-step transfer (stage + accept) so a typo can't brick admin.

// TransferOwnership stages a new owner; it takes effect only after AcceptOwnership
// is called BY that address.
func TransferOwnership(cur realm, newOwner address) {
	assertAdmin()
	if newOwner == "" {
		panic("newOwner must be non-empty")
	}
	pendingOwner = newOwner
	chain.Emit("OwnershipTransferStarted", "pending", newOwner.String())
}

// AcceptOwnership completes the handoff. Only the staged pendingOwner may call it.
func AcceptOwnership(cur realm) {
	if pendingOwner == "" {
		panic("no pending ownership transfer")
	}
	if unsafe.PreviousRealm().Address() != pendingOwner {
		panic("unauthorized: only the pending owner may accept")
	}
	owner = pendingOwner
	pendingOwner = ""
	chain.Emit("OwnershipTransferAccepted", "owner", owner.String())
}

// GetOwner returns the current admin address.
func GetOwner() string { return owner.String() }

// GetPendingOwner returns the staged owner ("" when no transfer is pending).
func GetPendingOwner() string { return pendingOwner.String() }

package memba_nft_market_v3_2

// v3.1 — structured read getters.
//
// These let the frontend read listings and offers STRUCTURALLY (full addresses,
// deterministic format) instead of scraping the markdown Render(""), which truncated
// addresses and capped at 50 rows. Output is one record per line, pipe-delimited, so
// the client parses by split — no markdown regex, no truncation.

import (
	"strings"

	"chain/runtime/unsafe"
)

// MaxPageSize bounds a single page so a getter can never iterate unboundedly (a
// gas/DoS surface). The frontend pages with offset/limit.
const MaxPageSize = 100

// MarketAddress returns this engine realm's own address — the operator a seller
// approves on the collection (SetApprovalForAll) and the address the collection
// registers via RegisterMarket. Exposed so the frontend and the deploy ceremony can
// read the deterministic address directly instead of hardcoding it.
func MarketAddress() string { return unsafe.CurrentRealm().Address().String() }

// ── NF-2 solvency getters (MAINNET_READINESS §3) ─────────────────────────────
//
// The offer escrow makes this a pooled-fund realm: without a machine-readable
// liabilities figure the solvency monitor can only do a balance-only heuristic.
// Invariant the monitor reconciles: realm balance >= TotalLiabilities().

// TotalLiabilities returns the total ugnot the realm owes to offer escrows.
// Maintained in lockstep with every escrow mutation (see offers.gno).
func TotalLiabilities() int64 { return totalEscrowed }

// RealmAddress is the NF-2 canonical name for the realm's own address (the
// monitor pairs it with TotalLiabilities). Same value as MarketAddress.
func RealmAddress() string { return MarketAddress() }

// ListingsCount returns the number of active listings (for pagination).
func ListingsCount() int { return len(listingOrder) }

// GetListingsPage returns a page of active listings, one per line:
//
//	collectionID|tokenID|seller|price|createdBlk
//
// Addresses are FULL (never truncated). offset/limit window the insertion-ordered
// listing set; limit is clamped to [1, MaxPageSize].
func GetListingsPage(offset, limit int) string {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > MaxPageSize {
		limit = MaxPageSize
	}
	n := len(listingOrder)
	end := offset + limit
	if end > n {
		end = n
	}

	var sb strings.Builder
	for i := offset; i < end; i++ {
		v, ok := listings.Get(listingOrder[i])
		if !ok {
			continue
		}
		l := v.(*Listing)
		sb.WriteString(l.CollectionID)
		sb.WriteString("|")
		sb.WriteString(l.TokenID)
		sb.WriteString("|")
		sb.WriteString(l.Seller.String())
		sb.WriteString("|")
		sb.WriteString(itoa(l.Price))
		sb.WriteString("|")
		sb.WriteString(itoa(l.CreatedBlk))
		sb.WriteString("\n")
	}
	return sb.String()
}

// GetOffersForToken returns the active offers on one (collection, token), one per line:
//
//	buyer|amount|createdBlk
//
// It uses a PREFIX-RANGE scan over the offer tree — offerKey is "collection:token:buyer",
// so the range ["collection:token:", "collection:token;") reads only this token's
// offers, never a full-tree scan. This is the read that finally lets the frontend wire
// accept-offer and show a token's offers (no offers getter existed before v3.1).
func GetOffersForToken(collectionID, tokenID string) string {
	start := collectionID + ":" + tokenID + ":"
	end := collectionID + ":" + tokenID + ";" // ';' (0x3b) is the byte after ':' (0x3a)

	var sb strings.Builder
	offers.Iterate(start, end, func(_ string, v interface{}) bool {
		o := v.(*Offer)
		sb.WriteString(o.Buyer.String())
		sb.WriteString("|")
		sb.WriteString(itoa(o.Amount))
		sb.WriteString("|")
		sb.WriteString(itoa(o.CreatedBlk))
		sb.WriteString("\n")
		return false
	})
	return sb.String()
}

package memba_nft_market_v3_2

// NFT Marketplace v3 — General-purpose NFT trading for the Memba ecosystem on test13.
//
// v3 is a fork of the audited memba_nft_market_v2 engine, repointed at the new
// canonical registry realm `memba_collections` (was `memba_nft_v2`). It keeps the
// proven structure: CEI payment ordering, IsUserCall guards on payable entrypoints,
// escrowed offers, GRC2981-style royalty settlement, and a platform-fee split.
//
// Changes vs v2:
//   1. Platform fee 2.5% → 2.0% (FeeBPS 250 → 200). See params.gno.
//   2. Every settlement event now carries the payment `denom` (forward-compat for
//      the GRC20 settlement desk; "ugnot" today). See SettlementDenom.
//   3. Settlement is reported via ONE canonical `Sale` event per sale, with a
//      `via` field = "buy" | "offer". v2 emitted BOTH `OfferAccepted` AND
//      `TokenSold` on an accepted offer, which double-counted volume in indexers.
//      v3 collapses that to the single `Sale` event (BuyNFT emits via="buy",
//      AcceptOffer emits via="offer"). The legacy `PurchaseConfirmed` /
//      `OfferAccepted` / `TokenSold` event names are intentionally retired.
//   4. Imports `memba_collections` for MarketTransfer / RoyaltyInfo. The collection
//      ABI is identical to v2's (same signatures), so no call-site adaptation was
//      needed beyond the import path.
//
// SCOPE (this engine): fixed-price listings (list/delist), buy, escrowed offers
// (make/cancel/accept/claim-expired), royalty settlement, platform-fee split,
// IsUserCall guards, pause.
//
// PHASE 3+ (deferred): the following are intentionally NOT built in this engine and
// are follow-on initiatives:
//   - Collection offers (offers on any token in a collection, not a specific id)
//   - Sweep (buy N cheapest listings in one tx)
//   - Auctions (timed / English / Dutch)
//   - GRC20 settlement desk (settle in $MEMBA or other GRC20; SettlementDenom is the
//     forward-compat hook already threaded onto every settlement event)
//   - DAO-curated badge (verified-collection curation)
//   - Points → $MEMBA claim (trading-rewards accrual + claim)
//
// Security:
//   - CEI (Checks-Effects-Interactions) in all payment flows
//   - IsUserCall guard on BuyNFT and MakeOffer (payment-bearing fns)
//   - Offer escrow with OfferTimeoutBlk safety valve (ClaimExpiredOffer)
//   - MinOfferLifetimeBlk prevents instant-cancel front-run
//   - Only original lister can delist (pause-exempt exit)
//   - Self-buy prevention
//   - Defense-in-depth royalty clamp even when collection enforces its own cap

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/samcrew/grc721"
	"gno.land/p/samcrew/avl"
	"gno.land/p/nt/ufmt/v0"

	core "gno.land/p/samcrew/memba_market_core_v2"   // v3.1: shared per-lane fee math (SplitProceedsBPS)
	cfg "gno.land/r/samcrew/memba_market_config"   // v3.1: DAO-owned per-lane fee + treasury spine
	nft "gno.land/r/samcrew/memba_collections"     // v3 change #4: canonical registry (was memba_nft_v2)
)

// laneNFT is this engine's lane key into the DAO fee config.
const laneNFT = "nft"

// resolveFee reads the NFT-lane protocol fee (bps) and treasury from the DAO config
// realm. It is FAIL-SAFE (panel C1): the config getters are pure and non-failing, and
// on any implausible value the engine falls back to its own constants rather than
// reverting a user's trade — a fee misconfig must never strand a settlement. The fee
// is clamped to [0, core.MaxFeeBPS] so a compromised config can't overcharge.
func resolveFee() (int64, address) {
	bps := int64(cfg.GetFeeBPS(laneNFT))
	if bps < 0 || bps > core.MaxFeeBPS {
		bps = FeeBPS // fallback to the engine's frozen default
	}
	treasury := cfg.GetTreasury()
	if treasury == "" {
		treasury = feeRecipient // fallback to the engine's local recipient
	}
	return bps, treasury
}

// ── Types ─────────────────────────────────────────────────────────────────────

// Listing represents a fixed-price sale order.
type Listing struct {
	CollectionID string
	TokenID      string
	Seller       address
	Price        int64
	CreatedBlk   int64
}

// Sale records a completed transaction for the salesLog.
type Sale struct {
	CollectionID string
	TokenID      string
	Seller       address
	Buyer        address
	Price        int64
	Fee          int64
	Royalty      int64
	Blk          int64
}

// ── State ─────────────────────────────────────────────────────────────────────

var (
	listings     *avl.Tree // listingKey -> *Listing
	offers       *avl.Tree // offerKey   -> *Offer
	salesLog     *avl.Tree // itoa(saleId) -> *Sale
	listingOrder []string  // insertion-ordered listing keys (pagination)
	nextSaleId   int64
	totalVolume  int64
	paused       bool
	feeRecipient = address(AdminAddress)

	// totalEscrowed is the sum of all ugnot currently held for open offers —
	// the realm's on-chain liabilities ledger (NF-2). Every escrow mutation
	// (MakeOffer / CancelOffer / ClaimExpiredOffer / AcceptOffer) keeps it in
	// lockstep with the offers tree, and TotalLiabilities() exposes it so the
	// solvency monitor can reconcile realm balance >= liabilities.
	totalEscrowed int64

	// owner is the current admin (2-step handoff — a hard-coded admin could
	// never be transferred to a DAO executor without redeploying the realm).
	// Initialized to AdminAddress; changed only via TransferOwnership +
	// AcceptOwnership by the staged address.
	owner        = address(AdminAddress)
	pendingOwner address
)

func init() {
	listings = avl.NewTree()
	offers = avl.NewTree()
	salesLog = avl.NewTree()
}

// ── Key helpers ───────────────────────────────────────────────────────────────

func listingKey(collectionID, tokenID string) string {
	return collectionID + ":" + tokenID
}

func offerKey(collectionID, tokenID string, buyer address) string {
	return collectionID + ":" + tokenID + ":" + string(buyer)
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// sumUgnot returns the total ugnot in a coin set.
func sumUgnot(coins chain.Coins) int64 {
	for _, c := range coins {
		if c.Denom == "ugnot" {
			return c.Amount
		}
	}
	return 0
}

// removeFromOrder removes a key from the ordered listing slice (O(n)).
func removeFromOrder(key string) {
	for i, k := range listingOrder {
		if k == key {
			listingOrder = append(listingOrder[:i], listingOrder[i+1:]...)
			return
		}
	}
}

// countListingsBySeller counts a seller's open listings. Bounded by MaxListings.
func countListingsBySeller(seller address) int {
	n := 0
	listings.Iterate("", "", func(_ string, v interface{}) bool {
		if v.(*Listing).Seller == seller {
			n++
		}
		return false
	})
	return n
}

// countOffersByBuyer counts a buyer's open offers. Bounded by MaxOffers.
func countOffersByBuyer(buyer address) int {
	n := 0
	offers.Iterate("", "", func(_ string, v interface{}) bool {
		if v.(*Offer).Buyer == buyer {
			n++
		}
		return false
	})
	return n
}

// ── List / Delist ─────────────────────────────────────────────────────────────

// ListNFT lists an NFT for fixed-price sale.
// PREREQUISITE: Owner must call memba_collections.SetApprovalForAll(collectionID,
// marketplace, true) first so MarketTransfer can execute on behalf of the seller.
func ListNFT(cur realm, collectionID string, tid grc721.TokenID, price int64) {
	if paused {
		panic("market paused")
	}
	seller := unsafe.PreviousRealm().Address()

	if price < MinPrice {
		panic(ufmt.Sprintf("price must be >= %d ugnot", MinPrice))
	}
	if price > MaxPrice {
		panic(ufmt.Sprintf("price must be <= %d ugnot", MaxPrice))
	}
	if listings.Size() >= MaxListings {
		panic("marketplace listing limit reached")
	}
	if countListingsBySeller(seller) >= MaxListingsPerAddr {
		panic("seller listing limit reached")
	}

	key := listingKey(collectionID, string(tid))
	if _, exists := listings.Get(key); exists {
		panic("already listed: " + key)
	}

	// Effects
	listings.Set(key, &Listing{
		CollectionID: collectionID,
		TokenID:      string(tid),
		Seller:       seller,
		Price:        price,
		CreatedBlk:   runtime.ChainHeight(),
	})
	listingOrder = append(listingOrder, key)

	chain.Emit("NFTListed",
		"collection", collectionID,
		"tokenId", string(tid),
		"seller", seller.String(),
		"price", itoa(price),
	)
}

// DelistNFT removes a listing. Only the original lister can delist. Pause-exempt
// (value-exit: unwinds the seller's position).
func DelistNFT(cur realm, collectionID string, tid grc721.TokenID) {
	caller := unsafe.PreviousRealm().Address()
	key := listingKey(collectionID, string(tid))

	val, exists := listings.Get(key)
	if !exists {
		panic("not listed: " + key)
	}
	l := val.(*Listing)
	if l.Seller != caller {
		panic("only seller can delist")
	}

	// Effects
	listings.Remove(key)
	removeFromOrder(key)

	chain.Emit("NFTDelisted",
		"collection", collectionID,
		"tokenId", string(tid),
		"seller", caller.String(),
	)
}

// ── Buy ───────────────────────────────────────────────────────────────────────

// BuyNFT purchases a listed NFT atomically (CEI order).
//
// CEI:
//   Checks  — paused / IsUserCall / listed / self-buy / payment amount
//   Effects — remove listing from state, record sale, update volume
//   Interactions — cross-call MarketTransfer, then banker payouts (seller last)
func BuyNFT(cur realm, collectionID string, tid grc721.TokenID) {
	if paused {
		panic("market paused")
	}
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("must be a direct user call")
	}
	key := listingKey(collectionID, string(tid))
	v, ok := listings.Get(key)
	if !ok {
		panic("listing not found")
	}
	l := v.(*Listing)
	buyer := unsafe.PreviousRealm().Address()
	if buyer == l.Seller {
		panic("cannot buy own listing")
	}
	if sumUgnot(unsafe.OriginSend()) != l.Price {
		panic("incorrect payment")
	}

	royRecip, royAmt := nft.RoyaltyInfo(collectionID, tid, l.Price)
	// v3.1: per-lane fee + treasury from the DAO config spine (fail-safe), settled via
	// the shared SplitProceedsBPS money-math.
	feeBps, treasury := resolveFee()
	fee, royalty, sellerAmt := core.SplitProceedsBPS(l.Price, feeBps, royAmt)

	// Effects (before cross-call + sends)
	seller := l.Seller
	price := l.Price
	listings.Remove(key)
	removeFromOrder(key)
	recordSale(collectionID, string(tid), seller, buyer, price, fee, royalty)
	totalVolume += price

	// Interactions
	nft.MarketTransfer(cross(cur), collectionID, seller, buyer, tid)
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := unsafe.CurrentRealm().Address()
	if royalty > 0 {
		bnk.SendCoins(self, royRecip, chain.Coins{chain.NewCoin("ugnot", royalty)})
	}
	if fee > 0 {
		bnk.SendCoins(self, treasury, chain.Coins{chain.NewCoin("ugnot", fee)})
	}
	bnk.SendCoins(self, seller, chain.Coins{chain.NewCoin("ugnot", sellerAmt)}) // seller last

	// v3 change #3: single canonical settlement event (via="buy").
	emitSale("buy", collectionID, string(tid), seller, buyer, price, fee, royalty, royRecip, sellerAmt, feeBps, treasury)
}

// ── emitSale ──────────────────────────────────────────────────────────────────

// emitSale emits the ONE canonical settlement event for a completed sale.
// v3 change #3: replaces v2's split PurchaseConfirmed / (OfferAccepted + TokenSold)
// events with a single `Sale` event keyed by `via` ("buy" | "offer"), so indexers
// count each sale exactly once. v3 change #2: carries the payment `denom`.
// v3.1: the event now also carries the `feeBps` and `treasury` ACTUALLY used for this
// settlement (read from the DAO config at settlement time), so the indexer and audit
// trail are authoritative even across a DAO fee/treasury change (panel M3).
func emitSale(via, collectionID, tokenID string, seller, buyer address, price, fee, royalty int64, royRecip address, sellerAmt, feeBps int64, treasury address) {
	chain.Emit("Sale",
		"via", via,
		"collection", collectionID,
		"tokenId", tokenID,
		"seller", seller.String(),
		"buyer", buyer.String(),
		"price", itoa(price),
		"fee", itoa(fee),
		"royalty", itoa(royalty),
		"royaltyRecipient", royRecip.String(),
		"sellerAmount", itoa(sellerAmt),
		"denom", SettlementDenom,
		"feeBps", itoa(feeBps),
		"treasury", treasury.String(),
		// schemaVersion last, per the memba_market_core_v2 event contract — lets the
		// indexer branch parsing deterministically (review finding H1).
		"schemaVersion", core.SchemaVersion,
	)
}

// v3.1: the three-way split now lives in p/samcrew/memba_market_core_v2 (SplitProceedsBPS),
// taking the per-lane fee bps so every engine shares one audited money-math
// implementation. The old local splitProceeds (hardcoded FeeBPS) was removed.

// ── recordSale ────────────────────────────────────────────────────────────────

func recordSale(collectionID, tokenID string, seller, buyer address, price, fee, royalty int64) {
	nextSaleId++
	salesLog.Set(itoa(nextSaleId), &Sale{
		CollectionID: collectionID,
		TokenID:      tokenID,
		Seller:       seller,
		Buyer:        buyer,
		Price:        price,
		Fee:          fee,
		Royalty:      royalty,
		Blk:          runtime.ChainHeight(),
	})
	// v3.2: keep the purchase-query indexes (sales_index.gno) in lockstep
	// with the log — HasPurchased must never lag a settled sale.
	indexSale(seller, buyer, nextSaleId)
}

// ── IsPaused ─────────────────────────────────────────────────────────────────

func IsPaused() bool { return paused }

// ── truncAddr / truncPath (render helpers) ────────────────────────────────────

func truncAddr(addr address) string {
	s := string(addr)
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

func truncPath(path string) string {
	parts := strings.Split(path, "/")
	if len(parts) > 2 {
		return parts[len(parts)-1]
	}
	return path
}

package memba_nft_market_v3_2

// Offer management — escrowed buyer offers on any listed NFT.
//
// Lifecycle:
//   MakeOffer      — buyer sends ugnot, funds held in escrow by this realm
//   CancelOffer    — buyer cancels (pause-exempt; must wait MinOfferLifetimeBlk)
//   AcceptOffer    — listing seller accepts; settles atomically via MarketTransfer + payouts
//   ClaimExpiredOffer — anyone claims refund after OfferTimeoutBlk (safety valve)
//
// Pause policy: MakeOffer + AcceptOffer are blocked while paused (new escrow /
// new settlement). CancelOffer + ClaimExpiredOffer are pause-exempt (value-exit).
//
// PHASE 3+ (deferred): collection-wide offers (an offer that matches ANY token in a
// collection rather than a specific token id) are NOT built here — see the deferred
// list in market.gno. This engine only supports per-token offers.

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/samcrew/grc721"
	"gno.land/p/nt/ufmt/v0"

	core "gno.land/p/samcrew/memba_market_core_v2" // v3.1: shared per-lane fee math
	nft "gno.land/r/samcrew/memba_collections"  // v3 change #4: canonical registry (was memba_nft_v2)
)

// Offer is an escrowed buy proposal on a specific (collection, token) pair.
type Offer struct {
	CollectionID string
	TokenID      string
	Buyer        address
	Amount       int64 // ugnot held in escrow
	CreatedBlk   int64
}

// MakeOffer places an offer with escrowed funds.
// Caller must send ugnot with the transaction; funds are held by this realm.
func MakeOffer(cur realm, collectionID string, tid grc721.TokenID) {
	if paused {
		panic("market paused")
	}
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("must be a direct user call")
	}
	buyer := unsafe.PreviousRealm().Address()
	amt := sumUgnot(unsafe.OriginSend())
	if amt < MinPrice {
		panic("offer below minimum")
	}

	if offers.Size() >= MaxOffers {
		panic("offer limit reached")
	}
	if countOffersByBuyer(buyer) >= MaxOffersPerAddr {
		panic("buyer offer limit reached")
	}

	key := offerKey(collectionID, string(tid), buyer)
	if _, exists := offers.Get(key); exists {
		panic("offer already exists, cancel first")
	}

	// Effects
	offers.Set(key, &Offer{
		CollectionID: collectionID,
		TokenID:      string(tid),
		Buyer:        buyer,
		Amount:       amt,
		CreatedBlk:   runtime.ChainHeight(),
	})
	totalEscrowed += amt // NF-2 liabilities ledger

	chain.Emit("OfferMade",
		"collection", collectionID,
		"tokenId", string(tid),
		"buyer", buyer.String(),
		"amount", itoa(amt),
	)
}

// CancelOffer allows the offerer to reclaim escrowed funds.
// Pause-exempt (value-exit). Must wait MinOfferLifetimeBlk to prevent front-run.
func CancelOffer(cur realm, collectionID string, tid grc721.TokenID) {
	caller := unsafe.PreviousRealm().Address()
	key := offerKey(collectionID, string(tid), caller)

	val, exists := offers.Get(key)
	if !exists {
		panic("offer not found")
	}
	o := val.(*Offer)

	age := runtime.ChainHeight() - o.CreatedBlk
	if age < MinOfferLifetimeBlk {
		panic(ufmt.Sprintf("offer too new to cancel: %d blocks remaining", MinOfferLifetimeBlk-age))
	}

	// Effects
	amt := o.Amount
	offers.Remove(key)
	totalEscrowed -= amt // NF-2 liabilities ledger

	// Interactions
	refund(cur, caller, amt)

	chain.Emit("OfferCancelled",
		"collection", collectionID,
		"tokenId", string(tid),
		"buyer", caller.String(),
		"amount", itoa(amt),
	)
}

// ClaimExpiredOffer returns escrowed funds when an offer has exceeded OfferTimeoutBlk.
// Pause-exempt (safety-valve: prevents permanent escrow lock).
// Anyone can call on behalf of the buyer, but funds always go to the buyer.
func ClaimExpiredOffer(cur realm, collectionID string, tid grc721.TokenID, buyer address) {
	key := offerKey(collectionID, string(tid), buyer)

	val, exists := offers.Get(key)
	if !exists {
		panic("offer not found")
	}
	o := val.(*Offer)

	age := runtime.ChainHeight() - o.CreatedBlk
	if age < OfferTimeoutBlk {
		panic(ufmt.Sprintf("offer not yet expired: %d blocks remaining", OfferTimeoutBlk-age))
	}

	// Effects
	amt := o.Amount
	offers.Remove(key)
	totalEscrowed -= amt // NF-2 liabilities ledger

	// Interactions
	refund(cur, buyer, amt)

	chain.Emit("OfferExpiredClaimed",
		"collection", collectionID,
		"tokenId", string(tid),
		"buyer", buyer.String(),
		"amount", itoa(amt),
	)
}

// AcceptOffer allows the listing seller to accept a buyer's escrowed offer.
// Requires an active listing (seller must have listed first).
// Settles atomically: cross-call MarketTransfer then pay royalty, fee, seller (seller last).
func AcceptOffer(cur realm, collectionID string, tid grc721.TokenID, buyer address) {
	if paused {
		panic("market paused")
	}
	seller := unsafe.PreviousRealm().Address()

	listKey := listingKey(collectionID, string(tid))
	lv, listed := listings.Get(listKey)
	if !listed {
		panic("AcceptOffer requires an active listing — list the NFT first")
	}
	l := lv.(*Listing)
	if l.Seller != seller {
		panic("only the listing seller can accept offers")
	}

	if buyer == seller {
		panic("cannot accept own offer")
	}

	oKey := offerKey(collectionID, string(tid), buyer)
	ov, exists := offers.Get(oKey)
	if !exists {
		panic("offer not found")
	}
	o := ov.(*Offer)

	royRecip, royAmt := nft.RoyaltyInfo(collectionID, tid, o.Amount)
	// v3.1: per-lane fee + treasury from the DAO config spine (fail-safe), shared math.
	feeBps, treasury := resolveFee()
	fee, royalty, sellerAmt := core.SplitProceedsBPS(o.Amount, feeBps, royAmt)

	// Effects (before cross-call + sends)
	amt := o.Amount
	offers.Remove(oKey)
	totalEscrowed -= amt // NF-2 liabilities ledger (escrow settles out)
	listings.Remove(listKey)
	removeFromOrder(listKey)
	recordSale(collectionID, string(tid), seller, buyer, amt, fee, royalty)
	totalVolume += amt

	// Interactions
	nft.MarketTransfer(cross(cur), collectionID, seller, buyer, tid)
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := unsafe.CurrentRealm().Address()
	if royalty > 0 {
		bnk.SendCoins(self, royRecip, chain.Coins{chain.NewCoin("ugnot", royalty)})
	}
	if fee > 0 {
		bnk.SendCoins(self, treasury, chain.Coins{chain.NewCoin("ugnot", fee)})
	}
	bnk.SendCoins(self, seller, chain.Coins{chain.NewCoin("ugnot", sellerAmt)}) // seller last

	// v3 change #3: ONE canonical settlement event (via="offer"). v2 emitted BOTH
	// OfferAccepted AND TokenSold here, double-counting the sale in indexers.
	emitSale("offer", collectionID, string(tid), seller, buyer, amt, fee, royalty, royRecip, sellerAmt, feeBps, treasury)
}

// refund sends escrowed ugnot back to a recipient from this realm's balance.
func refund(cur realm, to address, amt int64) {
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(unsafe.CurrentRealm().Address(), to, chain.Coins{chain.NewCoin("ugnot", amt)})
}

package memba_nft_market_v3_2

// Platform constants — single source of truth for all fee math and caps.

const (
	FeeBPS             = int64(200)                   // v3 change #1: 2.0% platform fee (was 2.5% / 250 bps in v2)
	MaxRoyaltyBPS      = int64(1000)                  // 10% maximum royalty (defense-in-depth clamp)
	MinPrice           = int64(1000)                  // 0.001 GNOT — prevents fee truncation to zero
	MaxPrice           = int64(1_000_000_000_000_000) // 1 billion GNOT
	OfferTimeoutBlk    = int64(302400)                // ~7 days at 2 s/block
	MinOfferLifetimeBlk = int64(10)                   // offer must live ≥ 10 blocks before cancel
	MaxListings        = 1000
	MaxOffers          = 1000
	MaxListingsPerAddr = 50
	MaxOffersPerAddr   = 50
	AdminAddress       = "g1x7k4628w93a7wzdhqc06atzx0v50rnshweuxu0"

	// v3 change #2: settlement payment denom. Carried on every settlement event for
	// forward-compat with the GRC20 settlement desk (PHASE 3+). Today, the engine
	// only settles in ugnot.
	SettlementDenom = "ugnot"
)

package memba_nft_market_v3_2

// Render — public read-only views.
//
// Routes:
//   ""       — home: active listings count + volume
//   "stats"  — platform fee, totals
//   "sales"  — recent sales (up to 20)
//   *        — 404

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	switch path {
	case "":
		return renderHome()
	case "stats":
		return renderStats()
	case "sales":
		return renderSales()
	default:
		return "# 404\nNot found: " + path
	}
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# NFT Marketplace\n\n")
	sb.WriteString(ufmt.Sprintf("**Active Listings:** %d\n", listings.Size()))
	volGnot := ufmt.Sprintf("%d.%06d", totalVolume/1_000_000, totalVolume%1_000_000)
	sb.WriteString(ufmt.Sprintf("**Total Volume:** %s GNOT\n", volGnot))

	if len(listingOrder) == 0 {
		sb.WriteString("\n*No active listings.*\n")
		return sb.String()
	}

	const homePageCap = 50

	sb.WriteString("\n| # | Collection | Token | Price | Seller |\n")
	sb.WriteString("|---|-----------|-------|-------|--------|\n")
	shown := 0
	for i, key := range listingOrder {
		if shown >= homePageCap {
			break
		}
		val, exists := listings.Get(key)
		if !exists {
			continue
		}
		l := val.(*Listing)
		priceGnot := ufmt.Sprintf("%d.%06d", l.Price/1_000_000, l.Price%1_000_000)
		sb.WriteString(ufmt.Sprintf("| %d | %s | %s | %s GNOT | %s |\n",
			i+1, truncPath(l.CollectionID), l.TokenID, priceGnot, truncAddr(l.Seller)))
		shown++
	}
	if len(listingOrder) > homePageCap {
		sb.WriteString(ufmt.Sprintf("\n*… showing first %d of %d listings.*\n", homePageCap, len(listingOrder)))
	}
	return sb.String()
}

// feePctString renders FeeBPS as a percent with two decimals (e.g. 200 bps -> "2.00").
// gno's ufmt parses width digits but drops the zero-pad flag, so "%02d" does NOT
// zero-pad — pad the fractional bps explicitly.
func feePctString() string {
	whole := FeeBPS / 100
	frac := FeeBPS % 100
	if frac < 10 {
		return ufmt.Sprintf("%d.0%d", whole, frac)
	}
	return ufmt.Sprintf("%d.%d", whole, frac)
}

func renderStats() string {
	var sb strings.Builder
	sb.WriteString("# Marketplace Stats\n\n")
	sb.WriteString(ufmt.Sprintf("**Active Listings:** %d\n", listings.Size()))
	sb.WriteString(ufmt.Sprintf("**Total Sales:** %d\n", salesLog.Size()))
	volGnot := ufmt.Sprintf("%d.%06d", totalVolume/1_000_000, totalVolume%1_000_000)
	sb.WriteString(ufmt.Sprintf("**Total Volume:** %s GNOT\n", volGnot))
	sb.WriteString(ufmt.Sprintf("**Active Offers:** %d\n", offers.Size()))
	sb.WriteString(ufmt.Sprintf("**Platform Fee:** %s%%\n", feePctString()))
	sb.WriteString(ufmt.Sprintf("**Max Royalty:** %d%%\n", MaxRoyaltyBPS/100))
	return sb.String()
}

func renderSales() string {
	var sb strings.Builder
	sb.WriteString("# Recent Sales\n\n")
	if salesLog.Size() == 0 {
		sb.WriteString("*No sales yet.*\n")
		return sb.String()
	}

	sb.WriteString("| Sale | Collection | Token | Price | Seller | Buyer |\n")
	sb.WriteString("|------|-----------|-------|-------|--------|-------|\n")

	count := 0
	salesLog.ReverseIterate("", "", func(key string, val interface{}) bool {
		s := val.(*Sale)
		priceGnot := ufmt.Sprintf("%d.%06d", s.Price/1_000_000, s.Price%1_000_000)
		sb.WriteString(ufmt.Sprintf("| %s | %s | %s | %s GNOT | %s | %s |\n",
			key, truncPath(s.CollectionID), s.TokenID, priceGnot,
			truncAddr(s.Seller), truncAddr(s.Buyer)))
		count++
		return count >= 20
	})
	return sb.String()
}

package memba_nft_market_v3_2

// v3.2 — purchase-query index + getters (the marketplace-v2 Phase 6 unlock).
//
// v3.1 recorded every settlement in salesLog but exposed NO purchase-query read,
// so purchase-gated reviews had nothing to gate on (ungated reputation is
// sybil-farmable — worse than none). v3.2 maintains two secondary indexes,
// written by the same recordSale that appends the log:
//
//	buyerSellerIdx  "buyer:seller"        -> int64 sale count
//	salesByBuyer    "buyer:pad(saleId)"   -> int64 saleId (per-buyer, sale order)
//
// and exposes HasPurchased / PurchaseCount / GetSalesByBuyer. Reads use the
// same prefix-range technique as GetOffersForToken (":" .. ";") — never a
// full-tree scan.
//
// Historical v3.1 sales enter through the sealed SeedSale migration: owner-only,
// NON-payable (never reads OriginSend / moves funds), one-way FinalizeSaleSeed
// latch — the exact SeedListing/FinalizeSeed precedent from memba_appstore_v3.

import (
	"strings"

	"chain"

	"gno.land/p/samcrew/avl"
)

var (
	buyerSellerIdx *avl.Tree // "buyer:seller" -> int64 count
	salesByBuyer   *avl.Tree // "buyer:pad(saleId)" -> int64 saleId
	saleSeedSealed bool
)

func init() {
	buyerSellerIdx = avl.NewTree()
	salesByBuyer = avl.NewTree()
}

// pad renders a saleId fixed-width so string ordering == numeric ordering
// inside a buyer's prefix range. 12 digits outlives any plausible sale count.
func pad(n int64) string {
	s := itoa(n)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

// indexSale is called by recordSale (and SeedSale) with an already-persisted
// sale. It only maintains the secondary indexes — salesLog stays the source
// of truth.
func indexSale(seller, buyer address, saleId int64) {
	bk := buyer.String() + ":" + seller.String()
	cnt := int64(0)
	if v, ok := buyerSellerIdx.Get(bk); ok {
		cnt = v.(int64)
	}
	buyerSellerIdx.Set(bk, cnt+1)
	salesByBuyer.Set(buyer.String()+":"+pad(saleId), saleId)
}

// ── Read getters (pure, non-failing) ─────────────────────────────────────────

// HasPurchased reports whether buyer has at least one settled purchase from
// seller on this engine. THE purchase-gate primitive for reviews: a consumer
// realm calls this before accepting a buyer's review of a seller.
func HasPurchased(buyerStr, sellerStr string) bool {
	return buyerSellerIdx.Has(buyerStr + ":" + sellerStr)
}

// PurchaseCount returns how many settled purchases buyer has made from seller.
func PurchaseCount(buyerStr, sellerStr string) int64 {
	if v, ok := buyerSellerIdx.Get(buyerStr + ":" + sellerStr); ok {
		return v.(int64)
	}
	return 0
}

// GetSalesByBuyer returns a page of the buyer's settled purchases in sale
// order, one per line:
//
//	saleId|collectionID|tokenID|seller|price|blk
//
// Addresses are FULL. limit is clamped to [1, MaxPageSize]; offset skips
// forward inside the buyer's prefix range (bounded by the page clamp — the
// iteration stops as soon as the page is full).
func GetSalesByBuyer(buyerStr string, offset, limit int) string {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > MaxPageSize {
		limit = MaxPageSize
	}
	start := buyerStr + ":"
	end := buyerStr + ";" // ';' (0x3b) is the byte after ':' (0x3a)

	var sb strings.Builder
	skipped, taken := 0, 0
	salesByBuyer.Iterate(start, end, func(_ string, v interface{}) bool {
		if skipped < offset {
			skipped++
			return false
		}
		if taken >= limit {
			return true // page full — stop iterating
		}
		saleId := v.(int64)
		sv, ok := salesLog.Get(itoa(saleId))
		if !ok {
			return false // index without log row — skip defensively
		}
		s := sv.(*Sale)
		sb.WriteString(itoa(saleId))
		sb.WriteString("|")
		sb.WriteString(s.CollectionID)
		sb.WriteString("|")
		sb.WriteString(s.TokenID)
		sb.WriteString("|")
		sb.WriteString(s.Seller.String())
		sb.WriteString("|")
		sb.WriteString(itoa(s.Price))
		sb.WriteString("|")
		sb.WriteString(itoa(s.Blk))
		sb.WriteString("\n")
		taken++
		return false
	})
	return sb.String()
}

// ── Migration (owner-only, sealable) ─────────────────────────────────────────

// SeedSale imports one historical v3.1 sale verbatim (its original block height,
// price and fee/royalty split). Owner-only, NON-payable, and permanently sealed
// by FinalizeSaleSeed — without the latch this would be a standing backdoor to
// forge purchase history and defeat the review gate.
func SeedSale(
	cur realm,
	collectionID, tokenID string,
	sellerStr, buyerStr string,
	price, fee, royalty, blk int64,
) {
	assertAdmin()
	if saleSeedSealed {
		panic("sale seeding sealed — migration is finalized")
	}
	if collectionID == "" || tokenID == "" {
		panic("empty collection/token id")
	}
	if sellerStr == "" || buyerStr == "" {
		panic("empty seller/buyer address")
	}
	if price < 0 || fee < 0 || royalty < 0 || fee+royalty > price {
		panic("invalid price/fee/royalty split")
	}
	if blk < 0 {
		panic("invalid block height")
	}
	seller := address(sellerStr)
	buyer := address(buyerStr)

	nextSaleId++
	salesLog.Set(itoa(nextSaleId), &Sale{
		CollectionID: collectionID,
		TokenID:      tokenID,
		Seller:       seller,
		Buyer:        buyer,
		Price:        price,
		Fee:          fee,
		Royalty:      royalty,
		Blk:          blk,
	})
	indexSale(seller, buyer, nextSaleId)
	// Keep the Render volume stat truthful across the migration.
	totalVolume += price
	chain.Emit("SaleSeeded", "saleId", itoa(nextSaleId), "collectionID", collectionID)
}

// FinalizeSaleSeed permanently seals SeedSale (one-way latch). Owner-only.
func FinalizeSaleSeed(cur realm) {
	assertAdmin()
	saleSeedSealed = true
	chain.Emit("SaleSeedingFinalized")
}
